def run(
    cmd,
    cwd=None,
    check=True,
):
    p = subprocess.run(
        [str(x) for x in cmd],
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
    )

    if check and p.returncode != 0:
        raise RuntimeError(
            "\nCommand failed:\n"
            + " ".join(
                str(x)
                for x in cmd
            )
            + "\n\n"
            + (p.stdout or "")
        )

    return (
        p.stdout or ""
    ).strip()


def git(
    *args,
    check=True,
):
    return run(
        ["git", *args],
        cwd=REPO,
        check=check,
    )


def load_json(path):
    return json.loads(
        Path(path).read_text(
            encoding="utf-8"
        )
    )


def human_bytes(n):
    n = int(n)

    units = [
        "B",
        "KiB",
        "MiB",
        "GiB",
        "TiB",
    ]

    value = float(n)

    for unit in units:
        if (
            value < 1024.0
            or unit == units[-1]
        ):
            return (
                f"{value:.3f} {unit}"
            )

        value /= 1024.0


def recurse_source_entries(obj):
    """
    Recover Stage20 source-file descriptors generically.
    Handles nested dict/list source structures.
    """

    found = []

    def walk(x):
        if isinstance(x, dict):

            if (
                "remote" in x
                and isinstance(
                    x["remote"],
                    str,
                )
            ):
                found.append(
                    {
                        key:
                            x.get(key)
                        for key
                        in [
                            "remote",
                            "revision",
                            "sha256",
                            "size_bytes",
                            "rows",
                        ]
                        if key in x
                    }
                )

            for value in x.values():
                walk(value)

        elif isinstance(x, list):
            for value in x:
                walk(value)

    walk(obj)

    return found


