def run(
    command,
    cwd=None,
    check=True,
):
    p = subprocess.run(
        [str(x) for x in command],
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
    )

    if (
        check
        and p.returncode != 0
    ):
        raise RuntimeError(
            "\nCommand failed:\n"
            + " ".join(
                str(x)
                for x
                in command
            )
            + "\n\n"
            + (
                p.stdout
                or ""
            )
        )

    return (
        p.stdout
        or ""
    ).strip()


def git(
    *args,
    check=True,
):
    return run(
        [
            "git",
            *args,
        ],
        cwd=REPO,
        check=check,
    )


def load_json(
    path,
):
    return json.loads(
        Path(
            path
        ).read_text(
            encoding="utf-8"
        )
    )


def human_bytes(
    value,
):
    value = float(
        value
    )

    for unit in [
        "B",
        "KiB",
        "MiB",
        "GiB",
        "TiB",
    ]:

        if (
            value < 1024.0
            or unit == "TiB"
        ):
            return (
                f"{value:.3f} {unit}"
            )

        value /= 1024.0


def recover_source_descriptors(
    obj,
):
    results = []

    def walk(
        x,
    ):
        if isinstance(
            x,
            dict,
        ):

            if (
                isinstance(
                    x.get(
                        "remote"
                    ),
                    str,
                )
            ):

                record = {}

                for key in [
                    "remote",
                    "revision",
                    "sha256",
                    "size_bytes",
                    "rows",
                ]:

                    if key in x:
                        record[
                            key
                        ] = x[
                            key
                        ]

                results.append(
                    record
                )

            for value in (
                x.values()
            ):
                walk(
                    value
                )

        elif isinstance(
            x,
            list,
        ):

            for value in x:
                walk(
                    value
                )

    walk(
        obj
    )

    return results


