def run(
    command,
    cwd=None,
    check=True,
):
    p = subprocess.run(
        [str(x) for x in command],
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
    )

    if check and p.returncode != 0:
        raise RuntimeError(
            "\nCommand failed:\n"
            + " ".join(
                str(x)
                for x in command
            )
            + "\n\n"
            + (p.stdout or "")
        )

    return (
        p.stdout or ""
    ).strip()


def git(
    *args,
):
    return run(
        ["git", *args],
        cwd=REPO,
    )


def sha256_file(
    path,
    chunk_size=64 * 1024 * 1024,
):
    h = hashlib.sha256()

    total = 0

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            chunk = f.read(
                chunk_size
            )

            if not chunk:
                break

            h.update(
                chunk
            )

            total += len(
                chunk
            )

            if (
                total
                // (1024**3)
                != (
                    total - len(chunk)
                )
                // (1024**3)
            ):
                print(
                    f"  hashed {total / 1024**3:.2f} GiB"
                )

    return h.hexdigest()


def resolved_path(
    path,
):
    return Path(
        os.path.realpath(
            str(path)
        )
    )


