def git(
    *args,
    auth_header=None,
    check=True,
):
    command = [
        "git",
    ]

    if auth_header is not None:

        command += [
            "-c",
            "credential.helper=",
            "-c",
            f"http.extraHeader=AUTHORIZATION: Basic {auth_header}",
        ]

    command += [
        str(x)
        for x in args
    ]

    return run(
        command,
        cwd=REPO,
        check=check,
    )


def load_json(
    path,
):
    return json.loads(
        Path(
            path
        ).read_text(
            encoding="utf-8"
        )
    )


def sha256_file(
    path,
    chunk_size=32 * 1024 * 1024,
):
    h = hashlib.sha256()

    total = 0

    with Path(
        path
    ).open(
        "rb"
    ) as fh:

        while True:

            chunk = fh.read(
                chunk_size
            )

            if not chunk:
                break

            h.update(
                chunk
            )

            total += len(
                chunk
            )

    return (
        h.hexdigest(),
        total,
    )


def write_json_sha(
    path,
    obj,
):
    path = Path(
        path
    )

    path.write_text(
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
            ensure_ascii=False,
        )
        + "\n",
        encoding="utf-8",
    )

    digest, _ = sha256_file(
        path
    )

    sha_path = Path(
        str(
            path
        )
        + ".sha256"
    )

    sha_path.write_text(
        f"{digest}  {path.name}\n",
        encoding="utf-8",
    )

    return digest


def exact_int(
    value,
    name,
):
    if value is None:

        raise RuntimeError(
            f"NULL frozen S4 field: {name}"
        )

    if isinstance(
        value,
        bool,
    ):

        return int(
            value
        )

    if isinstance(
        value,
        int,
    ):

        return int(
            value
        )

    number = float(
        value
    )

    if not math.isfinite(
        number
    ):

        raise RuntimeError(
            f"Non-finite S4 field {name}: {value!r}"
        )

    rounded = round(
        number
    )

    if number != rounded:

        raise RuntimeError(
            f"Non-integral S4 field {name}: {value!r}"
        )

    return int(
        rounded
    )


def normalize_column(
    name,
):
    return "".join(
        ch.lower()
        for ch
        in str(
            name
        )
        if ch.isalnum()
    )


def qident(
    name,
):
    return (
        '"'
        + str(
            name
        ).replace(
            '"',
            '""',
        )
        + '"'
    )


