def ensure_package(
    package,
    version=None,
):
    try:

        current = importlib.metadata.version(
            package
        )

    except importlib.metadata.PackageNotFoundError:

        current = None


    if (
        version is not None
        and current != version
    ):

        requirement = (
            f"{package}=={version}"
        )

        print(
            "Installing:",
            requirement,
        )

        subprocess.run(
            [
                sys.executable,
                "-m",
                "pip",
                "install",
                "-q",
                requirement,
            ],
            check=True,
        )

        current = importlib.metadata.version(
            package
        )


    elif current is None:

        print(
            "Installing:",
            package,
        )

        subprocess.run(
            [
                sys.executable,
                "-m",
                "pip",
                "install",
                "-q",
                package,
            ],
            check=True,
        )

        current = importlib.metadata.version(
            package
        )


    return current


