def resolve_column(
    key,
):
    hits = []

    for alias in ALIASES[
        key
    ]:

        hits.extend(
            normalized.get(
                alias,
                [],
            )
        )


    hits = list(
        dict.fromkeys(
            hits
        )
    )


    if len(
        hits
    ) != 1:

        raise RuntimeError(
            f"Cannot uniquely resolve {key}: {hits}"
        )


    return hits[
        0
    ]


