def timestamp_us(
    metadata,
    *,
    nanosecond_precision=False,
):
    if (
        hasattr(
            metadata,
            "sec",
        )
        and
        hasattr(
            metadata,
            "usec",
        )
    ):

        sec = int(
            metadata.sec
        )

        fractional = int(
            metadata.usec
        )


        if nanosecond_precision:

            fractional //= 1000


        return (
            sec
            * 1_000_000
            + fractional
        )


    if (
        hasattr(
            metadata,
            "tshigh",
        )
        and
        hasattr(
            metadata,
            "tslow",
        )
        and
        hasattr(
            metadata,
            "tsresol",
        )
    ):

        ticks = (
            (
                int(
                    metadata.tshigh
                )
                << 32
            )
            + int(
                metadata.tslow
            )
        )


        tsresol = int(
            metadata.tsresol
        )


        value, remainder = divmod(
            ticks
            * 1_000_000,
            tsresol,
        )


        if remainder != 0:

            raise RuntimeError(
                "PCAPNG timestamp not exactly microsecond representable."
            )


        return int(
            value
        )


    raise RuntimeError(
        f"Unsupported Scapy timestamp metadata: {metadata!r}"
    )


def java_signed_byte(
    value,
):
    value = int(
        value
    )

    return (
        value
        if value < 128
        else value - 256
    )


def historical_flow_key(
    src,
    dst,
    src_port,
    dst_port,
    protocol,
):
    forward = True


    for src_b, dst_b in zip(
        src,
        dst,
    ):

        s = java_signed_byte(
            src_b
        )

        d = java_signed_byte(
            dst_b
        )


        if s != d:

            if s > d:
                forward = False

            break


    if forward:

        return (
            bytes(
                src
            ),
            bytes(
                dst
            ),
            int(
                src_port
            ),
            int(
                dst_port
            ),
            int(
                protocol
            ),
        )


    return (
        bytes(
            dst
        ),
        bytes(
            src
        ),
        int(
            dst_port
        ),
        int(
            src_port
        ),
        int(
            protocol
        ),
    )


def ip_string(
    raw_ip,
):
    return socket.inet_ntoa(
        bytes(
            raw_ip
        )
    )


def flow_id_string(
    key,
):
    src, dst, sport, dport, proto = (
        key
    )

    return (
        f"{ip_string(src)}-"
        f"{ip_string(dst)}-"
        f"{sport}-"
        f"{dport}-"
        f"{proto}"
    )


def java_string_hash(
    value,
):
    h = 0


    for ch in str(
        value
    ):

        h = (
            31
            * h
            + ord(
                ch
            )
        ) & 0xFFFFFFFF


    return (
        h
        ^ (
            h
            >> 16
        )
    ) & 0xFFFFFFFF


def semantic_tcp_flags(
    tcp,
):
    value = int(
        tcp.flags
    )

    return {
        "FIN":
            bool(
                value
                & 0x01
            ),

        "SYN":
            bool(
                value
                & 0x02
            ),

        "RST":
            bool(
                value
                & 0x04
            ),

        "PSH":
            bool(
                value
                & 0x08
            ),

        "ACK":
            bool(
                value
                & 0x10
            ),

        "URG":
            bool(
                value
                & 0x20
            ),

        "ECE":
            bool(
                value
                & 0x40
            ),

        "CWR":
            bool(
                value
                & 0x80
            ),
    }


ZERO_FLAGS = {
    "FIN": False,
    "SYN": False,
    "RST": False,
    "PSH": False,
    "ACK": False,
    "URG": False,
    "ECE": False,
    "CWR": False,
}


def parse_packet(
    raw_bytes,
):
    """
    Frozen Stage20/Stage21 source-faithful S4 decoder.

    Representation-only packet-image bytes are intentionally omitted here:
    Stage24-1C is recovering S4 membership only.
    """

    pkt = Ether(
        raw_bytes
    )


    if IP not in pkt:

        return None


    ip = pkt[
        IP
    ]


    src_ip = str(
        ip.src
    )

    dst_ip = str(
        ip.dst
    )


    src = socket.inet_aton(
        src_ip
    )

    dst = socket.inet_aton(
        dst_ip
    )


    transport = ip.payload


    protocol = 0
    src_port = 0
    dst_port = 0

    flags = dict(
        ZERO_FLAGS
    )

    payload_length = 0

    parser_class = (
        "IPv4_OTHER_PROTOCOL_0"
    )


    if isinstance(
        transport,
        TCP,
    ):

        protocol = 6

        src_port = int(
            transport.sport
        )

        dst_port = int(
            transport.dport
        )

        payload_length = len(
            bytes(
                transport.payload
            )
        )

        flags = semantic_tcp_flags(
            transport
        )

        parser_class = (
            "IPv4_TCP"
        )


    elif isinstance(
        transport,
        UDP,
    ):

        protocol = 17

        src_port = int(
            transport.sport
        )

        dst_port = int(
            transport.dport
        )

        payload_length = len(
            bytes(
                transport.payload
            )
        )

        parser_class = (
            "IPv4_UDP"
        )


    return {
        "src":
            src,

        "dst":
            dst,

        "src_port":
            src_port,

        "dst_port":
            dst_port,

        "protocol":
            protocol,

        "payload_length":
            int(
                payload_length
            ),

        "fin":
            bool(
                flags[
                    "FIN"
                ]
            ),

        "syn":
            bool(
                flags[
                    "SYN"
                ]
            ),

        "rst":
            bool(
                flags[
                    "RST"
                ]
            ),

        "psh":
            bool(
                flags[
                    "PSH"
                ]
            ),

        "ack":
            bool(
                flags[
                    "ACK"
                ]
            ),

        "urg":
            bool(
                flags[
                    "URG"
                ]
            ),

        "ece":
            bool(
                flags[
                    "ECE"
                ]
            ),

        "cwr":
            bool(
                flags[
                    "CWR"
                ]
            ),

        "parser_class":
            parser_class,
    }


# ==============================================================================
# 10. FLOW STATE
# ==============================================================================

class FlowState:

    __slots__ = (
        "src",
        "dst",
        "src_port",
        "dst_port",
        "protocol",
        "start_us",
        "last_us",
        "packet_count",
        "fwd_count",
        "bwd_count",
        "fwd_sum",
        "bwd_sum",
        "fwd_min",
        "fwd_max",
        "bwd_min",
        "bwd_max",
        "flag_fin",
        "flag_syn",
        "flag_rst",
        "flag_psh",
        "flag_ack",
        "flag_urg",
        "flag_ece",
        "flag_cwr",
        "insertion_seq",
    )


    def __init__(
        self,
        packet,
        ts_us,
        insertion_seq,
        inherited_orientation=None,
    ):

        # Historical firstPacket() statistical direction is FWD.
        self.src = bytes(
            packet[
                "src"
            ]
        )

        self.dst = bytes(
            packet[
                "dst"
            ]
        )

        self.src_port = int(
            packet[
                "src_port"
            ]
        )

        self.dst_port = int(
            packet[
                "dst_port"
            ]
        )

        self.protocol = int(
            packet[
                "protocol"
            ]
        )


        self.start_us = int(
            ts_us
        )

        self.last_us = int(
            ts_us
        )


        payload = int(
            packet[
                "payload_length"
            ]
        )


        self.packet_count = 1

        self.fwd_count = 1
        self.bwd_count = 0

        self.fwd_sum = payload
        self.bwd_sum = 0

        self.fwd_min = payload
        self.fwd_max = payload

        self.bwd_min = 0
        self.bwd_max = 0


        # Historical BasicFlow.firstPacket() checkFlags().
        # addPacket() does NOT update these.
        self.flag_fin = int(
            bool(
                packet[
                    "fin"
                ]
            )
        )

        self.flag_syn = int(
            bool(
                packet[
                    "syn"
                ]
            )
        )

        self.flag_rst = int(
            bool(
                packet[
                    "rst"
                ]
            )
        )

        self.flag_psh = int(
            bool(
                packet[
                    "psh"
                ]
            )
        )

        self.flag_ack = int(
            bool(
                packet[
                    "ack"
                ]
            )
        )

        self.flag_urg = int(
            bool(
                packet[
                    "urg"
                ]
            )
        )

        self.flag_ece = int(
            bool(
                packet[
                    "ece"
                ]
            )
        )

        self.flag_cwr = int(
            bool(
                packet[
                    "cwr"
                ]
            )
        )


        self.insertion_seq = int(
            insertion_seq
        )


        # Historical timeout constructor overwrites output orientation only
        # AFTER first-packet statistical initialization.
        if inherited_orientation is not None:

            (
                inherited_src,
                inherited_dst,
                inherited_src_port,
                inherited_dst_port,
            ) = inherited_orientation


            self.src = bytes(
                inherited_src
            )

            self.dst = bytes(
                inherited_dst
            )

            self.src_port = int(
                inherited_src_port
            )

            self.dst_port = int(
                inherited_dst_port
            )


    def add_packet(
        self,
        packet,
        ts_us,
    ):

        payload = int(
            packet[
                "payload_length"
            ]
        )


        self.packet_count += 1


        # Historical direction comparison tests source IP only.
        if self.src == packet[
            "src"
        ]:

            self.fwd_count += 1

            self.fwd_sum += payload


            self.fwd_min = min(
                self.fwd_min,
                payload,
            )

            self.fwd_max = max(
                self.fwd_max,
                payload,
            )


        else:

            self.bwd_count += 1

            self.bwd_sum += payload


            if self.bwd_count == 1:

                self.bwd_min = payload
                self.bwd_max = payload


            else:

                self.bwd_min = min(
                    self.bwd_min,
                    payload,
                )

                self.bwd_max = max(
                    self.bwd_max,
                    payload,
                )


        self.last_us = int(
            ts_us
        )


    def s4_signature(
        self,
    ):
        # Historical physical serialization:
        #
        # physical FIN <- semantic RST
        # physical SYN <- semantic PSH
        # physical RST <- semantic ECE
        # physical PSH <- semantic SYN
        # physical ACK <- semantic ACK
        # physical URG <- semantic FIN

        return (
            ip_string(
                self.src
            ),

            int(
                self.src_port
            ),

            ip_string(
                self.dst
            ),

            int(
                self.dst_port
            ),

            int(
                self.protocol
            ),

            int(
                self.start_us
                // 1_000_000
            ),

            int(
                self.last_us
                - self.start_us
            ),

            int(
                self.fwd_count
            ),

            int(
                self.bwd_count
            ),

            int(
                self.fwd_sum
            ),

            int(
                self.bwd_sum
            ),

            int(
                self.fwd_min
            ),

            int(
                self.fwd_max
            ),

            int(
                self.bwd_min
            ),

            int(
                self.bwd_max
            ),

            int(
                self.flag_rst
            ),

            int(
                self.flag_psh
            ),

            int(
                self.flag_ece
            ),

            int(
                self.flag_syn
            ),

            int(
                self.flag_ack
            ),

            int(
                self.flag_fin
            ),
        )


# ==============================================================================
# 11. JAVA HASHMAP EOF ORDER
# ==============================================================================

class ActiveFlows:

    def __init__(
        self,
    ):

        self.map = {}

        self.capacity = 16

        self.threshold = 12

        self.next_insertion_seq = 0


    def __len__(
        self,
    ):

        return len(
            self.map
        )


    def get(
        self,
        key,
    ):

        return self.map.get(
            key
        )


    def remove(
        self,
        key,
    ):

        del self.map[
            key
        ]


    def put_new(
        self,
        key,
        flow,
    ):

        if key in self.map:

            raise RuntimeError(
                "Duplicate active flow key insertion."
            )


        if (
            len(
                self.map
            )
            + 1
            >
            self.threshold
        ):

            self.capacity *= 2

            self.threshold = int(
                self.capacity
                * 0.75
            )


        self.map[
            key
        ] = flow


    def create_flow(
        self,
        key,
        packet,
        ts_us,
        inherited_orientation=None,
    ):

        self.next_insertion_seq += 1


        flow = FlowState(
            packet=packet,
            ts_us=ts_us,
            insertion_seq=self.next_insertion_seq,
            inherited_orientation=inherited_orientation,
        )


        self.put_new(
            key,
            flow,
        )


        return flow


    def eof_items_historical_bucket_order(
        self,
    ):

        capacity = int(
            self.capacity
        )


        def order_key(
            item,
        ):

            key, flow = item


            bucket = (
                (
                    capacity
                    - 1
                )
                & java_string_hash(
                    flow_id_string(
                        key
                    )
                )
            )


            return (
                bucket,
                flow.insertion_seq,
            )


        return sorted(
            self.map.items(),
            key=order_key,
        )


# ==============================================================================
# 12. HISTORICAL FLOW GENERATOR
# ==============================================================================

def iterate_completed_flows(
    pcap_path,
    *,
    packet_limit=None,
    include_eof=False,
    progress_every=None,
):

    active = ActiveFlows()


    parser_counts = Counter()

    export_counts = Counter()


    raw_packet_count = 0

    valid_ipv4_count = 0

    exported_flow_count = 0

    exported_packet_total = 0

    timeout_singletons = 0


    reader = RawPcapReader(
        str(
            pcap_path
        )
    )


    pcap_nano = bool(
        getattr(
            reader,
            "nano",
            False,
        )
    )


    try:

        for raw_bytes, metadata in reader:

            raw_packet_count += 1


            parsed = parse_packet(
                raw_bytes
            )


            if parsed is None:

                parser_counts[
                    "NON_IPV4"
                ] += 1


            else:

                valid_ipv4_count += 1


                parser_counts[
                    parsed[
                        "parser_class"
                    ]
                ] += 1


                ts_us = timestamp_us(
                    metadata,
                    nanosecond_precision=pcap_nano,
                )


                key = historical_flow_key(
                    parsed[
                        "src"
                    ],
                    parsed[
                        "dst"
                    ],
                    parsed[
                        "src_port"
                    ],
                    parsed[
                        "dst_port"
                    ],
                    parsed[
                        "protocol"
                    ],
                )


                flow = active.get(
                    key
                )


                # ----------------------------------------------------------
                # New flow
                # FIN-first does NOT immediately close/export.
                # ----------------------------------------------------------

                if flow is None:

                    active.create_flow(
                        key,
                        parsed,
                        ts_us,
                    )


                # ----------------------------------------------------------
                # Timeout checked before FIN.
                # ----------------------------------------------------------

                elif (
                    ts_us
                    - flow.start_us
                    >
                    FLOW_TIMEOUT_US
                ):

                    inherited_orientation = (
                        bytes(
                            flow.src
                        ),
                        bytes(
                            flow.dst
                        ),
                        int(
                            flow.src_port
                        ),
                        int(
                            flow.dst_port
                        ),
                    )


                    if flow.packet_count > 1:

                        exported_flow_count += 1

                        exported_packet_total += int(
                            flow.packet_count
                        )

                        export_counts[
                            "FLOW_TIMEOUT"
                        ] += 1


                        yield (
                            "FLOW",
                            flow,
                            "FLOW_TIMEOUT",
                        )


                    else:

                        timeout_singletons += 1


                    active.remove(
                        key
                    )


                    active.create_flow(
                        key,
                        parsed,
                        ts_us,
                        inherited_orientation=inherited_orientation,
                    )


                # ----------------------------------------------------------
                # Existing matching flow + FIN.
                # ----------------------------------------------------------

                elif parsed[
                    "fin"
                ]:

                    flow.add_packet(
                        parsed,
                        ts_us,
                    )


                    exported_flow_count += 1

                    exported_packet_total += int(
                        flow.packet_count
                    )

                    export_counts[
                        "FIN"
                    ] += 1


                    yield (
                        "FLOW",
                        flow,
                        "FIN",
                    )


                    active.remove(
                        key
                    )


                # ----------------------------------------------------------
                # Normal packet.
                # ----------------------------------------------------------

                else:

                    flow.add_packet(
                        parsed,
                        ts_us,
                    )


            if (
                progress_every is not None
                and
                raw_packet_count
                % progress_every
                == 0
            ):

                yield (
                    "PROGRESS",
                    {
                        "raw_packets":
                            raw_packet_count,

                        "valid_ipv4":
                            valid_ipv4_count,

                        "active_flows":
                            len(
                                active
                            ),

                        "exported_flows":
                            exported_flow_count,
                    },
                    None,
                )


            if (
                packet_limit is not None
                and
                raw_packet_count
                >= packet_limit
            ):

                break


    finally:

        reader.close()


    eof_singletons = 0


    if include_eof:

        for key, flow in (
            active
            .eof_items_historical_bucket_order()
        ):

            if flow.packet_count > 1:

                exported_flow_count += 1

                exported_packet_total += int(
                    flow.packet_count
                )

                export_counts[
                    "EOF_CURRENT"
                ] += 1


                yield (
                    "FLOW",
                    flow,
                    "EOF_CURRENT",
                )


            else:

                eof_singletons += 1


    yield (
        "SUMMARY",
        {
            "raw_packet_count":
                int(
                    raw_packet_count
                ),

            "valid_ipv4_count":
                int(
                    valid_ipv4_count
                ),

            "parser_counts":
                dict(
                    parser_counts
                ),

            "export_counts":
                dict(
                    export_counts
                ),

            "exported_flow_count":
                int(
                    exported_flow_count
                ),

            "exported_packet_total":
                int(
                    exported_packet_total
                ),

            "active_flow_count_at_end":
                int(
                    len(
                        active
                    )
                ),

            "timeout_singletons":
                int(
                    timeout_singletons
                ),

            "eof_singletons":
                int(
                    eof_singletons
                ),

            "java_capacity":
                int(
                    active.capacity
                ),
        },
        None,
    )


