# ------------------------------------------------------------------------------
# 2. Ethernet -> IPv4 raw offset
# ------------------------------------------------------------------------------

VLAN_TYPES = {
    0x8100,
    0x88A8,
    0x9100,
    0x9200,
    0x9300,
}


def ipv4_offset_from_frame(raw_bytes):

    raw = memoryview(raw_bytes)

    if len(raw) < 14:
        return None

    ethertype = int.from_bytes(
        raw[12:14],
        "big",
    )

    offset = 14

    while ethertype in VLAN_TYPES:

        if len(raw) < offset + 4:
            return None

        ethertype = int.from_bytes(
            raw[offset + 2:offset + 4],
            "big",
        )

        offset += 4

    if ethertype != 0x0800:
        return None

    return offset


