def parse_packet_stage20_runtime(
    raw_bytes,
):

    pkt = Ether(
        raw_bytes
    )


    if IP not in pkt:

        return None


    ip = pkt[
        IP
    ]


    src = socket.inet_aton(
        str(ip.src)
    )

    dst = socket.inet_aton(
        str(ip.dst)
    )


    transport = ip.payload


    protocol = 0

    src_port = 0

    dst_port = 0

    payload_length = 0

    flags = dict(
        ZERO_FLAGS
    )

    parser_class = (
        "IPv4_OTHER_PROTOCOL_0"
    )


    if isinstance(
        transport,
        TCP,
    ):

        tcp = transport


        protocol = 6

        src_port = int(
            tcp.sport
        )

        dst_port = int(
            tcp.dport
        )


        flags = semantic_tcp_flags(
            tcp
        )


        offset = ipv4_offset_from_frame(
            raw_bytes
        )


        if offset is None:

            raise RuntimeError(
                "TCP packet missing recoverable IPv4 raw offset."
            )


        captured_ipv4_extent = (
            len(raw_bytes)
            - offset
        )


        payload_length = (
            captured_ipv4_extent
            -
            int(ip.ihl) * 4
            -
            int(tcp.dataofs) * 4
        )


        if payload_length < 0:

            raise RuntimeError(
                "Negative captured TCP payload length."
            )


        parser_class = (
            "IPv4_TCP"
        )


    elif isinstance(
        transport,
        UDP,
    ):

        udp = transport


        protocol = 17

        src_port = int(
            udp.sport
        )

        dst_port = int(
            udp.dport
        )


        payload_length = len(
            bytes(
                udp.payload
            )
        )


        parser_class = (
            "IPv4_UDP"
        )


    return {
        "src":
            src,

        "dst":
            dst,

        "src_port":
            src_port,

        "dst_port":
            dst_port,

        "protocol":
            protocol,

        "payload_length":
            int(
                payload_length
            ),

        "fin":
            bool(
                flags["FIN"]
            ),

        "syn":
            bool(
                flags["SYN"]
            ),

        "rst":
            bool(
                flags["RST"]
            ),

        "psh":
            bool(
                flags["PSH"]
            ),

        "ack":
            bool(
                flags["ACK"]
            ),

        "urg":
            bool(
                flags["URG"]
            ),

        "ece":
            bool(
                flags["ECE"]
            ),

        "cwr":
            bool(
                flags["CWR"]
            ),

        "parser_class":
            parser_class,
    }


