# ==============================================================================
# 2. RAW ETHERNET -> IPV4 OFFSET
# ==============================================================================

VLAN_TYPES = {
    0x8100,
    0x88A8,
    0x9100,
    0x9200,
    0x9300,
}


def ipv4_offset_from_frame(
    raw_bytes,
):

    raw = memoryview(
        raw_bytes
    )

    if len(raw) < 14:
        return None


    ethertype = int.from_bytes(
        raw[12:14],
        "big",
    )


    offset = 14


    while ethertype in VLAN_TYPES:

        if len(raw) < offset + 4:
            return None


        ethertype = int.from_bytes(
            raw[
                offset + 2:
                offset + 4
            ],
            "big",
        )


        offset += 4


    if ethertype != 0x0800:
        return None


    return int(
        offset
    )


# ==============================================================================
# 3. CAPTURE EXTENT CANDIDATES
# ==============================================================================

def safe_len_original(
    packet,
):
    value = getattr(
        packet,
        "original",
        None,
    )

    if value is None:
        return None

    try:
        return len(
            value
        )

    except Exception:
        return None


def metadata_value(
    metadata,
    names,
):

    for name in names:

        if hasattr(
            metadata,
            name,
        ):

            value = getattr(
                metadata,
                name,
            )

            if value is not None:

                try:
                    return int(
                        value
                    )

                except Exception:
                    pass

    return None


def get_candidate_extents(
    raw_bytes,
    metadata,
    ip,
    tcp,
):

    offset = ipv4_offset_from_frame(
        raw_bytes
    )


    if offset is None:
        return {}


    ip_h = (
        int(
            ip.ihl
        )
        * 4
    )


    tcp_h = (
        int(
            tcp.dataofs
        )
        * 4
    )


    candidates = {}


    # --------------------------------------------------------------------------
    # A. Exact raw frame slice
    # --------------------------------------------------------------------------

    candidates[
        "RAW_FRAME_MINUS_L2"
    ] = (
        len(
            raw_bytes
        )
        - offset
    )


    # --------------------------------------------------------------------------
    # B. Scapy original IPv4 dissection bytes
    # --------------------------------------------------------------------------

    ip_original_len = safe_len_original(
        ip
    )


    if ip_original_len is not None:

        candidates[
            "LEN_IP_ORIGINAL"
        ] = (
            ip_original_len
        )


    # --------------------------------------------------------------------------
    # C. Current Scapy serialized IPv4 object
    # --------------------------------------------------------------------------

    try:

        candidates[
            "LEN_BYTES_IP"
        ] = len(
            bytes(
                ip
            )
        )

    except Exception:
        pass


    # --------------------------------------------------------------------------
    # D. TCP.original plus IP header
    # --------------------------------------------------------------------------

    tcp_original_len = safe_len_original(
        tcp
    )


    if tcp_original_len is not None:

        candidates[
            "IP_HEADER_PLUS_LEN_TCP_ORIGINAL"
        ] = (
            ip_h
            +
            tcp_original_len
        )


    # --------------------------------------------------------------------------
    # E. Direct Scapy TCP payload extent
    # --------------------------------------------------------------------------

    try:

        candidates[
            "HEADERS_PLUS_LEN_BYTES_TCP_PAYLOAD"
        ] = (
            ip_h
            +
            tcp_h
            +
            len(
                bytes(
                    tcp.payload
                )
            )
        )

    except Exception:
        pass


    # --------------------------------------------------------------------------
    # F. PCAP captured length metadata
    # --------------------------------------------------------------------------

    caplen = metadata_value(
        metadata,
        [
            "caplen",
            "incl_len",
            "wirelen",
        ],
    )


    if caplen is not None:

        # If the metadata includes whole Ethernet frame.
        if caplen >= offset:

            candidates[
                "METADATA_CAPTURE_LEN_MINUS_L2"
            ] = (
                caplen
                -
                offset
            )


    # --------------------------------------------------------------------------
    # G. Explicit wire length if separately exposed
    # --------------------------------------------------------------------------

    wirelen = metadata_value(
        metadata,
        [
            "wirelen",
            "orig_len",
        ],
    )


    if wirelen is not None:

        if wirelen >= offset:

            candidates[
                "METADATA_WIRE_LEN_MINUS_L2"
            ] = (
                wirelen
                -
                offset
            )


    return candidates


