print("=" * 112)


active = {}

exported_packet_indices = []

parser_counts = Counter()
reason_counts = Counter()

reader = RawPcapReader(
    str(PCAP)
)

pcap_nano = bool(
    getattr(
        reader,
        "nano",
        False,
    )
)


try:

    for raw_packet_index, (
        raw_bytes,
        metadata,
    ) in enumerate(reader):

        if raw_packet_index >= 50_000:
            break


        packet = geometry_packet(
            raw_bytes
        )


        if packet is None:

            parser_counts[
                "NON_IPV4"
            ] += 1

            continue


        if packet["protocol"] == 6:

            parser_counts[
                "IPv4_TCP"
            ] += 1

        elif packet["protocol"] == 17:

            parser_counts[
                "IPv4_UDP"
            ] += 1

        else:

            parser_counts[
                "IPv4_OTHER_PROTOCOL_0"
            ] += 1


        ts_us = timestamp_us(
            metadata,
            nanosecond_precision=pcap_nano,
        )


        key = historical_flow_key(
            packet["src"],
            packet["dst"],
            packet["sport"],
            packet["dport"],
            packet["protocol"],
        )


        state = active.get(
            key
        )


        # ----------------------------------------------------------------------
        # New flow.
        # ----------------------------------------------------------------------

        if state is None:

            active[key] = {
                "start_us":
                    int(ts_us),

                "packet_indices":
                    [
                        int(raw_packet_index)
                    ],
            }

            continue


        # ----------------------------------------------------------------------
        # Timeout before FIN, exactly as frozen lifecycle.
        # ----------------------------------------------------------------------

        if (
            int(ts_us)
            -
            state["start_us"]
            >
            FLOW_TIMEOUT_US
        ):

            if len(
                state[
                    "packet_indices"
                ]
            ) > 1:

                exported_packet_indices.append(
                    list(
                        state[
                            "packet_indices"
                        ]
                    )
                )

                reason_counts[
                    "FLOW_TIMEOUT"
                ] += 1


            active.pop(
                key
            )


            active[key] = {
                "start_us":
                    int(ts_us),

                "packet_indices":
                    [
                        int(raw_packet_index)
                    ],
            }

            continue


        # ----------------------------------------------------------------------
        # Existing flow + FIN.
        # ----------------------------------------------------------------------

        if packet[
            "fin"
        ]:

            state[
                "packet_indices"
            ].append(
                int(
                    raw_packet_index
                )
            )


            exported_packet_indices.append(
                list(
                    state[
                        "packet_indices"
                    ]
                )
            )


            reason_counts[
                "FIN"
            ] += 1


            active.pop(
                key
            )

            continue


        # ----------------------------------------------------------------------
        # Normal packet.
        # ----------------------------------------------------------------------

        state[
            "packet_indices"
        ].append(
            int(
                raw_packet_index
            )
        )


finally:

    reader.close()


