# ==============================================================================
# 3. DIRECT CLASSIC-PCAP ITERATOR
#
# Keeps BOTH:
#   incl_len = bytes physically stored in file
#   orig_len = original/wire packet length in record header
# ==============================================================================

def iter_classic_pcap(path):

    contract = inspect_pcap_header(
        path
    )

    endian = contract["endian"]

    nano = contract["nano"]

    record_struct = struct.Struct(
        endian + "IIII"
    )

    with open(path, "rb") as fh:

        global_header = fh.read(24)

        if len(global_header) != 24:
            raise RuntimeError(
                "PCAP global header disappeared."
            )

        packet_index = 0

        while True:

            header = fh.read(16)

            if not header:
                break

            if len(header) != 16:
                raise RuntimeError(
                    f"Truncated PCAP record header at "
                    f"packet {packet_index}"
                )

            (
                ts_sec,
                ts_fraction,
                incl_len,
                orig_len,
            ) = record_struct.unpack(
                header
            )

            raw_bytes = fh.read(
                incl_len
            )

            if len(raw_bytes) != incl_len:
                raise RuntimeError(
                    f"Truncated PCAP record payload at "
                    f"packet {packet_index}"
                )

            if nano:

                # Frozen lifecycle uses integer microseconds.
                ts_us = (
                    int(ts_sec)
                    * 1_000_000
                    +
                    int(ts_fraction)
                    // 1000
                )

            else:

                ts_us = (
                    int(ts_sec)
                    * 1_000_000
                    +
                    int(ts_fraction)
                )

            yield {
                "index":
                    int(packet_index),

                "ts_us":
                    int(ts_us),

                "incl_len":
                    int(incl_len),

                "orig_len":
                    int(orig_len),

                "raw_bytes":
                    raw_bytes,
            }

            packet_index += 1


# ==============================================================================
# 4. L2 -> IPV4 OFFSET
# ==============================================================================

VLAN_TYPES = {
    0x8100,
    0x88A8,
    0x9100,
    0x9200,
    0x9300,
}


def ipv4_offset_from_frame(raw_bytes):

    raw = memoryview(raw_bytes)

    if len(raw) < 14:
        return None

    ethertype = int.from_bytes(
        raw[12:14],
        "big",
    )

    offset = 14

    while ethertype in VLAN_TYPES:

        if len(raw) < offset + 4:
            return None

        ethertype = int.from_bytes(
            raw[offset + 2:offset + 4],
            "big",
        )

        offset += 4

    if ethertype != 0x0800:
        return None

    return int(offset)


