# ==============================================================================
# 2. ETHERNET IPV4 OFFSET
# ==============================================================================

VLAN_TYPES = {
    0x8100,
    0x88A8,
    0x9100,
    0x9200,
    0x9300,
}


def ipv4_offset_from_frame(raw_bytes):

    raw = memoryview(
        raw_bytes
    )

    if len(raw) < 14:

        return None


    ethertype = int.from_bytes(
        raw[12:14],
        "big",
    )

    offset = 14


    while ethertype in VLAN_TYPES:

        if len(raw) < offset + 4:

            return None


        ethertype = int.from_bytes(
            raw[
                offset + 2:
                offset + 4
            ],
            "big",
        )

        offset += 4


    if ethertype != 0x0800:

        return None


    return int(
        offset
    )


# ==============================================================================
# 3. PCAPNG OPTION PARSER
# ==============================================================================

def parse_options(
    data,
    endian,
):

    options = {}

    pos = 0


    while pos + 4 <= len(data):

        code, length = struct.unpack_from(
            endian + "HH",
            data,
            pos,
        )

        pos += 4


        if code == 0:

            break


        value = data[
            pos:
            pos + length
        ]


        options.setdefault(
            int(code),
            [],
        ).append(
            bytes(value)
        )


        pos += (
            (
                length
                + 3
            )
            // 4
        ) * 4


    return options


def decode_ts_resolution(
    options,
):

    # PCAPNG default is 10^-6 seconds.
    if 9 not in options:

        return Fraction(
            1,
            1_000_000,
        )


    raw = options[
        9
    ][
        0
    ]


    if len(raw) < 1:

        raise RuntimeError(
            "Malformed if_tsresol option."
        )


    value = int(
        raw[
            0
        ]
    )


    if value & 0x80:

        exponent = (
            value
            & 0x7F
        )

        return Fraction(
            1,
            2 ** exponent,
        )


    return Fraction(
        1,
        10 ** value,
    )


def decode_ts_offset(
    options,
    endian,
):

    # if_tsoffset option code 14, signed 64-bit seconds.
    if 14 not in options:

        return 0


    raw = options[
        14
    ][
        0
    ]


    if len(raw) != 8:

        raise RuntimeError(
            "Malformed if_tsoffset option."
        )


    return int(
        struct.unpack(
            endian + "q",
            raw,
        )[
            0
        ]
    )


# ==============================================================================
# 4. DIRECT PCAPNG ITERATOR
#
# Supports:
#   SHB 0x0A0D0D0A
#   IDB 0x00000001
#   EPB 0x00000006
#
# We fail closed if the packet population uses an unexpected packet-block type.
# ==============================================================================

SHB = 0x0A0D0D0A
IDB = 0x00000001
EPB = 0x00000006
SPB = 0x00000003
PB  = 0x00000002


def iter_pcapng_records(
    path,
):

    fh = open(
        path,
        "rb",
    )


    try:

        endian = None

        interfaces = []

        packet_index = 0


        while True:

            first8 = fh.read(
                8
            )


            if not first8:

                break


            if len(first8) != 8:

                raise RuntimeError(
                    "Truncated PCAPNG block header."
                )


            raw_type = first8[
                :4
            ]


            # ------------------------------------------------------------------
            # Section Header Block is endian-discovery point.
            # ------------------------------------------------------------------

            if raw_type == b"\x0a\x0d\x0d\x0a":

                bom_and_rest = fh.read(
                    4
                )


                if len(bom_and_rest) != 4:

                    raise RuntimeError(
                        "Truncated PCAPNG SHB BOM."
                    )


                bom = bom_and_rest


                if bom == b"\x4d\x3c\x2b\x1a":

                    endian = "<"


                elif bom == b"\x1a\x2b\x3c\x4d":

                    endian = ">"


                else:

                    raise RuntimeError(
                        "Invalid PCAPNG byte-order magic: "
                        + bom.hex()
                    )


                block_total_length = struct.unpack(
                    endian + "I",
                    first8[
                        4:8
                    ],
                )[
                    0
                ]


                if block_total_length < 28:

                    raise RuntimeError(
                        "Invalid SHB block length."
                    )


                # Already consumed 12 bytes.
                remainder = fh.read(
                    block_total_length
                    - 12
                )


                if len(remainder) != (
                    block_total_length
                    - 12
                ):

                    raise RuntimeError(
                        "Truncated SHB."
                    )


                trailing = struct.unpack(
                    endian + "I",
                    remainder[
                        -4:
                    ],
                )[
                    0
                ]


                if trailing != block_total_length:

                    raise RuntimeError(
                        "SHB trailing length mismatch."
                    )


                # New section resets interface IDs.
                interfaces = []

                continue


            if endian is None:

                raise RuntimeError(
                    "PCAPNG block encountered before SHB."
                )


            block_type = struct.unpack(
                endian + "I",
                raw_type,
            )[
                0
            ]


            block_total_length = struct.unpack(
                endian + "I",
                first8[
                    4:8
                ],
            )[
                0
            ]


            if block_total_length < 12:

                raise RuntimeError(
                    f"Invalid block length: {block_total_length}"
                )


            remaining = fh.read(
                block_total_length
                - 8
            )


            if len(remaining) != (
                block_total_length
                - 8
            ):

                raise RuntimeError(
                    "Truncated PCAPNG block."
                )


            body = remaining[
                :-4
            ]


            trailing_length = struct.unpack(
                endian + "I",
                remaining[
                    -4:
                ],
            )[
                0
            ]


            if trailing_length != block_total_length:

                raise RuntimeError(
                    "PCAPNG trailing block-length mismatch."
                )


            # ------------------------------------------------------------------
            # Interface Description Block
            # ------------------------------------------------------------------

            if block_type == IDB:

                if len(body) < 8:

                    raise RuntimeError(
                        "Malformed IDB."
                    )


                linktype, reserved, snaplen = struct.unpack_from(
                    endian + "HHI",
                    body,
                    0,
                )


                options = parse_options(
                    body[
                        8:
                    ],
                    endian,
                )


                ts_resolution = decode_ts_resolution(
                    options
                )


                ts_offset = decode_ts_offset(
                    options,
                    endian,
                )


                interfaces.append(
                    {
                        "linktype":
                            int(
                                linktype
                            ),

                        "snaplen":
                            int(
                                snaplen
                            ),

                        "ts_resolution":
                            ts_resolution,

                        "ts_offset":
                            int(
                                ts_offset
                            ),
                    }
                )


                continue


            # ------------------------------------------------------------------
            # Enhanced Packet Block
            # ------------------------------------------------------------------

            if block_type == EPB:

                if len(body) < 20:

                    raise RuntimeError(
                        "Malformed EPB."
                    )


                (
                    interface_id,
                    ts_high,
                    ts_low,
                    captured_len,
                    original_len,
                ) = struct.unpack_from(
                    endian + "IIIII",
                    body,
                    0,
                )


                interface_id = int(
                    interface_id
                )


                if interface_id >= len(
                    interfaces
                ):

                    raise RuntimeError(
                        f"Unknown EPB interface: {interface_id}"
                    )


                interface = interfaces[
                    interface_id
                ]


                if interface[
                    "linktype"
                ] != 1:

                    raise RuntimeError(
                        "Stage20 Monday expected Ethernet LINKTYPE 1; "
                        f"got {interface['linktype']}."
                    )


                captured_len = int(
                    captured_len
                )


                original_len = int(
                    original_len
                )


                packet_start = 20

                packet_end = (
                    packet_start
                    + captured_len
                )


                if packet_end > len(
                    body
                ):

                    raise RuntimeError(
                        f"EPB captured length exceeds block at packet "
                        f"{packet_index}."
                    )


                raw_bytes = bytes(
                    body[
                        packet_start:
                        packet_end
                    ]
                )


                ticks = (
                    (
                        int(
                            ts_high
                        )
                        << 32
                    )
                    |
                    int(
                        ts_low
                    )
                )


                ts_seconds = (
                    Fraction(
                        ticks,
                        1,
                    )
                    *
                    interface[
                        "ts_resolution"
                    ]
                    +
                    interface[
                        "ts_offset"
                    ]
                )


                ts_microseconds = (
                    ts_seconds
                    * 1_000_000
                )


                if ts_microseconds.denominator != 1:

                    raise RuntimeError(
                        "Frozen timestamp is not integer-microsecond "
                        f"representable at packet {packet_index}: "
                        f"{ts_microseconds}"
                    )


                yield {
                    "index":
                        int(
                            packet_index
                        ),

                    "raw_bytes":
                        raw_bytes,

                    "captured_len":
                        captured_len,

                    "original_len":
                        original_len,

                    "ts_us":
                        int(
                            ts_microseconds
                        ),
                }


                packet_index += 1

                continue


            # ------------------------------------------------------------------
            # Fail closed if actual packet blocks other than EPB appear.
            # ------------------------------------------------------------------

            if block_type in {
                SPB,
                PB,
            }:

                raise RuntimeError(
                    "Monday PCAPNG contains non-EPB packet block type "
                    f"{block_type:#x}; parser extension required."
                )


            # Other metadata blocks are ignored.


    finally:

        fh.close()


