# ==============================================================================
# 7. HISTORICAL EXTENT FUNCTION
# ==============================================================================

def historical_ipv4_extent(
    record,
    l2_offset,
):

    if (
        CAPTURE_RULE
        ==
        "PCAPNG_CAPTURED_LEN_MINUS_L2"
    ):

        return (
            int(
                record[
                    "captured_len"
                ]
            )
            -
            l2_offset
        )


    if (
        CAPTURE_RULE
        ==
        "PCAPNG_ORIGINAL_LEN_MINUS_L2"
    ):

        return (
            int(
                record[
                    "original_len"
                ]
            )
            -
            l2_offset
        )


    if (
        CAPTURE_RULE
        ==
        "DIRECT_PACKET_BYTES_MINUS_L2"
    ):

        return (
            len(
                record[
                    "raw_bytes"
                ]
            )
            -
            l2_offset
        )


    raise RuntimeError(
        CAPTURE_RULE
    )


# ==============================================================================
# 8. STAGE20 PACKET DECODER
# ==============================================================================

def parse_stage20_packet_from_record(
    record,
):

    raw_bytes = record[
        "raw_bytes"
    ]


    pkt = Ether(
        raw_bytes
    )


    if IP not in pkt:

        return None


    ip = pkt[
        IP
    ]


    src = socket.inet_aton(
        str(
            ip.src
        )
    )

    dst = socket.inet_aton(
        str(
            ip.dst
        )
    )


    transport = ip.payload


    protocol = 0

    src_port = 0

    dst_port = 0

    payload_length = 0

    flags = dict(
        ZERO_FLAGS
    )

    parser_class = (
        "IPv4_OTHER_PROTOCOL_0"
    )


    if isinstance(
        transport,
        TCP,
    ):

        tcp = transport


        protocol = 6

        src_port = int(
            tcp.sport
        )

        dst_port = int(
            tcp.dport
        )


        flags = semantic_tcp_flags(
            tcp
        )


        offset = ipv4_offset_from_frame(
            raw_bytes
        )


        if offset is None:

            raise RuntimeError(
                "TCP packet missing IPv4 offset."
            )


        captured_ipv4_extent = (
            historical_ipv4_extent(
                record,
                offset,
            )
        )


        payload_length = (
            captured_ipv4_extent
            -
            int(
                ip.ihl
            )
            * 4
            -
            int(
                tcp.dataofs
            )
            * 4
        )


        if payload_length < 0:

            raise RuntimeError(
                f"Negative Stage20 TCP payload at packet "
                f"{record['index']}."
            )


        parser_class = (
            "IPv4_TCP"
        )


    elif isinstance(
        transport,
        UDP,
    ):

        udp = transport


        protocol = 17

        src_port = int(
            udp.sport
        )

        dst_port = int(
            udp.dport
        )


        # Already-frozen Stage20 UDP rule.
        payload_length = len(
            bytes(
                udp.payload
            )
        )


        parser_class = (
            "IPv4_UDP"
        )


    return {
        "src":
            src,

        "dst":
            dst,

        "src_port":
            src_port,

        "dst_port":
            dst_port,

        "protocol":
            protocol,

        "payload_length":
            int(
                payload_length
            ),

        "fin":
            bool(
                flags[
                    "FIN"
                ]
            ),

        "syn":
            bool(
                flags[
                    "SYN"
                ]
            ),

        "rst":
            bool(
                flags[
                    "RST"
                ]
            ),

        "psh":
            bool(
                flags[
                    "PSH"
                ]
            ),

        "ack":
            bool(
                flags[
                    "ACK"
                ]
            ),

        "urg":
            bool(
                flags[
                    "URG"
                ]
            ),

        "ece":
            bool(
                flags[
                    "ECE"
                ]
            ),

        "cwr":
            bool(
                flags[
                    "CWR"
                ]
            ),

        "parser_class":
            parser_class,
    }


# ==============================================================================
# 9. HISTORICAL FLOW ITERATOR
# ==============================================================================

def iterate_completed_flows_stage20_pcapng(
    pcap_path,
    *,
    packet_limit=None,
    include_eof=False,
    progress_every=None,
):

    active = ActiveFlows()


    parser_counts = Counter()

    export_counts = Counter()


    raw_packet_count = 0

    valid_ipv4_count = 0

    exported_flow_count = 0

    exported_packet_total = 0

    timeout_singletons = 0


    for record in iter_pcapng_records(
        pcap_path
    ):

        if (
            packet_limit is not None
            and
            raw_packet_count
            >= packet_limit
        ):

            break


        raw_packet_count += 1


        parsed = (
            parse_stage20_packet_from_record(
                record
            )
        )


        if parsed is None:

            parser_counts[
                "NON_IPV4"
            ] += 1


        else:

            valid_ipv4_count += 1


            parser_counts[
                parsed[
                    "parser_class"
                ]
            ] += 1


            ts_us = int(
                record[
                    "ts_us"
                ]
            )


            key = historical_flow_key(
                parsed[
                    "src"
                ],
                parsed[
                    "dst"
                ],
                parsed[
                    "src_port"
                ],
                parsed[
                    "dst_port"
                ],
                parsed[
                    "protocol"
                ],
            )


            flow = active.get(
                key
            )


            # --------------------------------------------------------------
            # First packet
            # --------------------------------------------------------------

            if flow is None:

                active.create_flow(
                    key,
                    parsed,
                    ts_us,
                )


            # --------------------------------------------------------------
            # Timeout before FIN
            # --------------------------------------------------------------

            elif (
                ts_us
                -
                flow.start_us
                >
                FLOW_TIMEOUT_US
            ):

                inherited_orientation = (
                    bytes(
                        flow.src
                    ),
                    bytes(
                        flow.dst
                    ),
                    int(
                        flow.src_port
                    ),
                    int(
                        flow.dst_port
                    ),
                )


                if flow.packet_count > 1:

                    exported_flow_count += 1


                    exported_packet_total += int(
                        flow.packet_count
                    )


                    export_counts[
                        "FLOW_TIMEOUT"
                    ] += 1


                    yield (
                        "FLOW",
                        flow,
                        "FLOW_TIMEOUT",
                    )


                else:

                    timeout_singletons += 1


                active.remove(
                    key
                )


                active.create_flow(
                    key,
                    parsed,
                    ts_us,
                    inherited_orientation=(
                        inherited_orientation
                    ),
                )


            # --------------------------------------------------------------
            # Existing flow + FIN
            # --------------------------------------------------------------

            elif parsed[
                "fin"
            ]:

                flow.add_packet(
                    parsed,
                    ts_us,
                )


                exported_flow_count += 1


                exported_packet_total += int(
                    flow.packet_count
                )


                export_counts[
                    "FIN"
                ] += 1


                yield (
                    "FLOW",
                    flow,
                    "FIN",
                )


                active.remove(
                    key
                )


            # --------------------------------------------------------------
            # Normal packet
            # --------------------------------------------------------------

            else:

                flow.add_packet(
                    parsed,
                    ts_us,
                )


        if (
            progress_every is not None
            and
            raw_packet_count
            % progress_every
            == 0
        ):

            yield (
                "PROGRESS",
                {
                    "raw_packets":
                        int(
                            raw_packet_count
                        ),

                    "valid_ipv4":
                        int(
                            valid_ipv4_count
                        ),

                    "active_flows":
                        int(
                            len(
                                active
                            )
                        ),

                    "exported_flows":
                        int(
                            exported_flow_count
                        ),
                },
                None,
            )


    eof_singletons = 0


    if include_eof:

        for key, flow in (
            active
            .eof_items_historical_bucket_order()
        ):

            if flow.packet_count > 1:

                exported_flow_count += 1


                exported_packet_total += int(
                    flow.packet_count
                )


                export_counts[
                    "EOF_CURRENT"
                ] += 1


                yield (
                    "FLOW",
                    flow,
                    "EOF_CURRENT",
                )


            else:

                eof_singletons += 1


    yield (
        "SUMMARY",
        {
            "raw_packet_count":
                int(
                    raw_packet_count
                ),

            "valid_ipv4_count":
                int(
                    valid_ipv4_count
                ),

            "parser_counts":
                dict(
                    parser_counts
                ),

            "export_counts":
                dict(
                    export_counts
                ),

            "exported_flow_count":
                int(
                    exported_flow_count
                ),

            "exported_packet_total":
                int(
                    exported_packet_total
                ),

            "active_flow_count_at_end":
                int(
                    len(
                        active
                    )
                ),

            "timeout_singletons":
                int(
                    timeout_singletons
                ),

            "eof_singletons":
                int(
                    eof_singletons
                ),

            "java_capacity":
                int(
                    active.capacity
                ),
        },
        None,
    )


# Keep this live for the next full Monday cell.
