def run_cmd(
    args,
    *,
    cwd=None,
    check=True,
):

    p = subprocess.run(
        [str(x) for x in args],
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
    )

    if (
        check
        and
        p.returncode != 0
    ):

        raise RuntimeError(
            "\nCommand failed:\n"
            + " ".join(str(x) for x in args)
            + "\n\n"
            + (p.stdout or "")
        )

    return (
        p.stdout
        or ""
    ).strip()


def git_cmd(
    *args,
    auth_header=None,
    check=True,
):

    cmd = [
        "git",
    ]

    if auth_header is not None:

        cmd += [
            "-c",
            "credential.helper=",
            "-c",
            f"http.extraHeader=AUTHORIZATION: Basic {auth_header}",
        ]

    cmd += [
        str(x)
        for x in args
    ]

    return run_cmd(
        cmd,
        cwd=REPO,
        check=check,
    )


def sha256_file(
    path,
    chunk_size=16 * 1024 * 1024,
):

    h = hashlib.sha256()

    size = 0

    with Path(path).open(
        "rb"
    ) as fh:

        while True:

            chunk = fh.read(
                chunk_size
            )

            if not chunk:
                break

            h.update(
                chunk
            )

            size += len(
                chunk
            )

    return (
        h.hexdigest(),
        size,
    )


def write_json(
    path,
    obj,
):

    Path(path).write_text(
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
            ensure_ascii=False,
        )
        + "\n",
        encoding="utf-8",
    )


