matched_reason_counts = Counter()


raw_unmatched = 0
d5_excluded_count = 0

flow_index = 0

full_summary = None


full_started = time.time()


for kind, payload, reason in iterate_stage20_flows(
    PCAP,
    packet_limit=None,
    include_eof=True,
    progress_every=500_000,
):

    if kind == "PROGRESS":

        elapsed = payload[
            "elapsed_seconds"
        ]


        print(
            f" packets={payload['raw_packets']:,}"
            f" | ipv4={payload['valid_ipv4']:,}"
            f" | exported={payload['exported_flows']:,}"
            f" | active={payload['active_flows']:,}"
            f" | grounded={len(matched_row_indices):,}"
            f" | elapsed={elapsed / 60:.1f} min",
            flush=True,
        )

        continue


    if kind == "SUMMARY":

        full_summary = payload

        continue


    idx = int(
        flow_index
    )


    flow_index += 1


    signature = (
        payload.s4_signature()
    )


    entry = label_entries.get(
        signature
    )


    already = int(
        consumed.get(
            signature,
            0,
        )
    )


    available = (
        0
        if entry is None
        else
        int(
            entry[
                1
            ]
        )
        -
        already
    )


    raw_exact = (
        available > 0
    )


    # --------------------------------------------------------------------------
    # Frozen D5 source-faithful exclusions.
    #
    # They were raw exact but MUST NOT consume a published occurrence.
    # --------------------------------------------------------------------------

    if idx in D5_EXCLUDED:

        if not raw_exact:

            raise RuntimeError(
                f"Frozen D5 flow {idx} is no longer raw exact."
            )


        expected_duration = {
            471: 224,
            473: 262,
        }[
            idx
        ]


        duration = int(
            payload.last_us
            -
            payload.start_us
        )


        if (
            int(
                payload.protocol
            ) != 6
            or
            duration != expected_duration
            or
            reason != "FIN"
        ):

            raise RuntimeError(
                f"D5 anchor failure at {idx}."
            )


        d5_excluded_count += 1

        continue


    # --------------------------------------------------------------------------
    # No exact published occurrence remaining.
    # --------------------------------------------------------------------------

    if not raw_exact:

        raw_unmatched += 1

        continue


    # --------------------------------------------------------------------------
    # Deterministically consume one published physical occurrence.
    # --------------------------------------------------------------------------

    locator = entry[
        2
    ]


    if isinstance(
        locator,
        int,
    ):

        if already != 0:

            raise RuntimeError(
                "Unique published S4 consumed more than once."
            )


        published_row = int(
            locator
        )


    else:

        if already >= len(
            locator
        ):

            raise RuntimeError(
                "Duplicate published S4 cursor overflow."
            )


        published_row = int(
            locator[
                already
            ]
        )


    consumed[
        signature
    ] = (
        already
        + 1
    )


    binary = int(
        entry[
            0
        ]
    )


    matched_row_indices.append(
        published_row
    )


    matched_flow_indices.append(
        idx
    )


    matched_binary_labels.append(
        binary
    )


    matched_reason_codes.append(
        REASON_TO_CODE[
            reason
        ]
    )


    matched_binary_counts[
        binary
    ] += 1


    matched_reason_counts[
        reason
    ] += 1


