# ==============================================================================
# 1. HELPERS
# ==============================================================================

def sha256_file(
    path,
    chunk_size=32 * 1024 * 1024,
):

    path = Path(
        path
    )

    h = hashlib.sha256()

    total = 0


    with path.open(
        "rb"
    ) as fh:

        while True:

            chunk = fh.read(
                chunk_size
            )

            if not chunk:
                break


            h.update(
                chunk
            )

            total += len(
                chunk
            )


    return (
        h.hexdigest(),
        total,
    )


def human_gib(
    value,
):

    return (
        float(
            value
        )
        /
        1024**3
    )


