# ==============================================================================
# 3. COMPACT PACKET DECODER
#
# Input bytes are the Stage20 MASKED IPv4 representation.
#
# Masking does NOT alter:
#   - protocol
#   - ports
#   - TCP flags
#   - application payload
#   - retained packet length
#
# For retained length <256, the entire captured IPv4 representation is known to
# be present because Stage20 stored min(original_length, 256).
# ==============================================================================

def decode_compact_packet(
    packet_bytes,
):

    raw = bytes(
        packet_bytes
    )


    if len(raw) < 20:
        raise RuntimeError(
            f"Compact IPv4 packet too short: {len(raw)}"
        )


    ip = sall.IP(
        raw
    )


    transport = ip.payload


    if isinstance(
        transport,
        sall.TCP,
    ):

        tcp = transport

        flag_value = int(
            tcp.flags
        )


        return {
            "protocol":
                6,

            "sport":
                int(
                    tcp.sport
                ),

            "dport":
                int(
                    tcp.dport
                ),

            "payload":
                int(
                    len(
                        bytes(
                            tcp.payload
                        )
                    )
                ),

            "semantic_fin":
                int(
                    bool(
                        flag_value
                        &
                        0x01
                    )
                ),

            "semantic_syn":
                int(
                    bool(
                        flag_value
                        &
                        0x02
                    )
                ),

            "semantic_rst":
                int(
                    bool(
                        flag_value
                        &
                        0x04
                    )
                ),

            "semantic_psh":
                int(
                    bool(
                        flag_value
                        &
                        0x08
                    )
                ),

            "semantic_ack":
                int(
                    bool(
                        flag_value
                        &
                        0x10
                    )
                ),

            "semantic_urg":
                int(
                    bool(
                        flag_value
                        &
                        0x20
                    )
                ),

            "semantic_ece":
                int(
                    bool(
                        flag_value
                        &
                        0x40
                    )
                ),
        }


    if isinstance(
        transport,
        sall.UDP,
    ):

        udp = transport


        return {
            "protocol":
                17,

            "sport":
                int(
                    udp.sport
                ),

            "dport":
                int(
                    udp.dport
                ),

            "payload":
                int(
                    len(
                        bytes(
                            udp.payload
                        )
                    )
                ),

            "semantic_fin": 0,
            "semantic_syn": 0,
            "semantic_rst": 0,
            "semantic_psh": 0,
            "semantic_ack": 0,
            "semantic_urg": 0,
            "semantic_ece": 0,
        }


    return {
        "protocol": 0,
        "sport": 0,
        "dport": 0,
        "payload": 0,

        "semantic_fin": 0,
        "semantic_syn": 0,
        "semantic_rst": 0,
        "semantic_psh": 0,
        "semantic_ack": 0,
        "semantic_urg": 0,
        "semantic_ece": 0,
    }


# ==============================================================================
# 4. DECODE ONLY 428 AMBIGUOUS CORPUS FLOWS
# ==============================================================================

print("=" * 112)
print("DECODING 428 AMBIGUOUS CORPUS FLOWS")
print("=" * 112)


corpus_flow_info = {}


for ordinal, corpus_index in enumerate(
    corpus_ambiguous_idx,
    start=1,
):

    corpus_index = int(
        corpus_index
    )


    flow_lengths = np.asarray(
        lengths[
            corpus_index
        ],
        dtype=np.uint16,
    )


    packet_count_stored = int(
        np.count_nonzero(
            flow_lengths
        )
    )


    start = int(
        offsets[
            corpus_index
        ]
    )


    cursor = start


    packets = []


    for position in range(
        packet_count_stored
    ):

        retained_len = int(
            flow_lengths[
                position
            ]
        )


        if retained_len <= 0:
            raise RuntimeError(
                (
                    "Unexpected zero inside compact packet prefix",
                    corpus_index,
                    position,
                )
            )


        packet = bytes(
            encoded[
                cursor:
                cursor + retained_len
            ]
        )


        cursor += retained_len


        decoded = decode_compact_packet(
            packet
        )


        decoded[
            "retained_len"
        ] = retained_len


        decoded[
            "full_capture_known"
        ] = (
            retained_len
            <
            256
        )


        packets.append(
            decoded
        )


    if cursor != int(
        offsets[
            corpus_index + 1
        ]
    ):
        raise RuntimeError(
            f"Offset traversal mismatch at corpus row {corpus_index}"
        )


    first = packets[
        0
    ]


    # Historical physical flag serialization:
    #
    # physical FIN <- semantic RST
    # physical SYN <- semantic PSH
    # physical RST <- semantic ECE
    # physical PSH <- semantic SYN
    # physical ACK <- semantic ACK
    # physical URG <- semantic FIN
    physical_flags = {
        "fin":
            int(
                first[
                    "semantic_rst"
                ]
            ),

        "syn":
            int(
                first[
                    "semantic_psh"
                ]
            ),

        "rst":
            int(
                first[
                    "semantic_ece"
                ]
            ),

        "psh":
            int(
                first[
                    "semantic_syn"
                ]
            ),

        "ack":
            int(
                first[
                    "semantic_ack"
                ]
            ),

        "urg":
            int(
                first[
                    "semantic_fin"
                ]
            ),
    }


    corpus_flow_info[
        corpus_index
    ] = {
        "packet_count_stored":
            packet_count_stored,

        "all_packets_full":
            all(
                item[
                    "full_capture_known"
                ]
                for item in packets
            ),

        "protocol":
            int(
                first[
                    "protocol"
                ]
            ),

        "first_sport":
            int(
                first[
                    "sport"
                ]
            ),

        "first_dport":
            int(
                first[
                    "dport"
                ]
            ),

        "flags":
            physical_flags,

        "packets":
            packets,
    }


    if (
        ordinal
        %
        100
        ==
        0
    ):

        print(
            f"  decoded {ordinal:,} / {corpus_ambiguous_idx.size:,}",
            flush=True,
        )


print(
    "[PASS] Ambiguous compact flows decoded."
)

print()


# ==============================================================================
# 5. SAFE CANDIDATE COMPATIBILITY
# ==============================================================================

def candidate_compatible(
    flow,
    candidate,
):

    protocol = int(
        flow[
            "protocol"
        ]
    )


    # --------------------------------------------------------------------------
    # Exact literal protocol.
    # --------------------------------------------------------------------------

    if int(
        candidate[
            "protocol"
        ]
    ) != protocol:

        return False


    packets = flow[
        "packets"
    ]


    stored_n = int(
        flow[
            "packet_count_stored"
        ]
    )


    total_n = (
        int(
            candidate[
                "fwd_count"
            ]
        )
        +
        int(
            candidate[
                "bwd_count"
            ]
        )
    )


    # --------------------------------------------------------------------------
    # Representation row count.
    # --------------------------------------------------------------------------

    if stored_n < 64:

        # Representation contains the complete flow.
        if total_n != stored_n:
            return False

        candidate_complete = True


    else:

        if total_n < 64:
            return False

        candidate_complete = (
            total_n
            ==
            64
        )


    # --------------------------------------------------------------------------
    # Exact directed ports.
    # --------------------------------------------------------------------------

    cand_sport = int(
        candidate[
            "src_port"
        ]
    )

    cand_dport = int(
        candidate[
            "dst_port"
        ]
    )


    if protocol == 0:

        if (
            cand_sport != 0
            or
            cand_dport != 0
        ):
            return False


    else:

        first_sport = int(
            flow[
                "first_sport"
            ]
        )

        first_dport = int(
            flow[
                "first_dport"
            ]
        )


        if (
            cand_sport,
            cand_dport,
        ) not in {
            (
                first_sport,
                first_dport,
            ),
            (
                first_dport,
                first_sport,
            ),
        }:

            return False


    # --------------------------------------------------------------------------
    # Frozen first-packet physical flags.
    # --------------------------------------------------------------------------

    for name in (
        "fin",
        "syn",
        "rst",
        "psh",
        "ack",
        "urg",
    ):

        if int(
            candidate[
                name
            ]
        ) != int(
            flow[
                "flags"
            ][
                name
            ]
        ):

            return False


    # --------------------------------------------------------------------------
    # Payload geometry can only be exact/bounded when every stored packet was
    # persisted below the 256-byte truncation boundary.
    # --------------------------------------------------------------------------

    all_full = bool(
        flow[
            "all_packets_full"
        ]
    )


    if not all_full:

        # Still a valid compatibility candidate; do not infer from truncated
        # payload bytes.
        return True


    # --------------------------------------------------------------------------
    # Same-port or protocol-0 flows:
    #
    # Source IP was intentionally masked, so direction cannot be reconstructed
    # from transport ports. Use only direction-invariant constraints.
    # --------------------------------------------------------------------------

    if (
        protocol == 0
        or
        cand_sport == cand_dport
    ):

        payloads = [
            int(
                pkt[
                    "payload"
                ]
            )
            for pkt in packets
        ]


        prefix_sum = sum(
            payloads
        )


        candidate_sum = (
            int(
                candidate[
                    "fwd_sum"
                ]
            )
            +
            int(
                candidate[
                    "bwd_sum"
                ]
            )
        )


        if candidate_complete:

            if candidate_sum != prefix_sum:
                return False


            global_max = max(
                payloads
            )


            candidate_global_max = max(
                int(
                    candidate[
                        "fwd_max"
                    ]
                ),
                int(
                    candidate[
                        "bwd_max"
                    ]
                ),
            )


            if candidate_global_max != global_max:
                return False


            nonempty_direction_mins = [
                int(
                    candidate[
                        "fwd_min"
                    ]
                )
            ]


            if int(
                candidate[
                    "bwd_count"
                ]
            ) > 0:

                nonempty_direction_mins.append(
                    int(
                        candidate[
                            "bwd_min"
                        ]
                    )
                )


            candidate_global_min = min(
                nonempty_direction_mins
            )


            if candidate_global_min != min(
                payloads
            ):
                return False


        else:

            # Only a stored 64-packet prefix.
            if candidate_sum < prefix_sum:
                return False


        return True


    # --------------------------------------------------------------------------
    # Distinct TCP/UDP ports.
    #
    # Historical quirk:
    #   packet 0 is ALWAYS statistically FWD before timeout orientation
    #   overwrite.
    #
    # Subsequent packet direction is determined against final output
    # orientation, represented by candidate source/destination ports.
    # --------------------------------------------------------------------------

    fwd_payloads = [
        int(
            packets[
                0
            ][
                "payload"
            ]
        )
    ]

    bwd_payloads = []


    for packet in packets[
        1:
    ]:

        packet_ports = (
            int(
                packet[
                    "sport"
                ]
            ),
            int(
                packet[
                    "dport"
                ]
            ),
        )


        if packet_ports == (
            cand_sport,
            cand_dport,
        ):

            fwd_payloads.append(
                int(
                    packet[
                        "payload"
                    ]
                )
            )


        elif packet_ports == (
            cand_dport,
            cand_sport,
        ):

            bwd_payloads.append(
                int(
                    packet[
                        "payload"
                    ]
                )
            )


        else:

            # Packet cannot belong to candidate orientation.
            return False


    prefix_fwd_count = len(
        fwd_payloads
    )

    prefix_bwd_count = len(
        bwd_payloads
    )


    cand_fwd_count = int(
        candidate[
            "fwd_count"
        ]
    )

    cand_bwd_count = int(
        candidate[
            "bwd_count"
        ]
    )


    prefix_fwd_sum = sum(
        fwd_payloads
    )

    prefix_bwd_sum = sum(
        bwd_payloads
    )


    if candidate_complete:

        # Exact complete-flow geometry.
        if cand_fwd_count != prefix_fwd_count:
            return False

        if cand_bwd_count != prefix_bwd_count:
            return False

        if int(
            candidate[
                "fwd_sum"
            ]
        ) != prefix_fwd_sum:
            return False

        if int(
            candidate[
                "bwd_sum"
            ]
        ) != prefix_bwd_sum:
            return False


        if int(
            candidate[
                "fwd_min"
            ]
        ) != min(
            fwd_payloads
        ):
            return False

        if int(
            candidate[
                "fwd_max"
            ]
        ) != max(
            fwd_payloads
        ):
            return False


        if prefix_bwd_count == 0:

            if int(
                candidate[
                    "bwd_min"
                ]
            ) != 0:
                return False

            if int(
                candidate[
                    "bwd_max"
                ]
            ) != 0:
                return False


        else:

            if int(
                candidate[
                    "bwd_min"
                ]
            ) != min(
                bwd_payloads
            ):
                return False

            if int(
                candidate[
                    "bwd_max"
                ]
            ) != max(
                bwd_payloads
            ):
                return False


    else:

        # Safe bounds for a >64-packet flow.
        if cand_fwd_count < prefix_fwd_count:
            return False

        if cand_bwd_count < prefix_bwd_count:
            return False

        if int(
            candidate[
                "fwd_sum"
            ]
        ) < prefix_fwd_sum:
            return False

        if int(
            candidate[
                "bwd_sum"
            ]
        ) < prefix_bwd_sum:
            return False


        if int(
            candidate[
                "fwd_max"
            ]
        ) < max(
            fwd_payloads
        ):
            return False


        if int(
            candidate[
                "fwd_min"
            ]
        ) > min(
            fwd_payloads
        ):
            return False


        if prefix_bwd_count > 0:

            if int(
                candidate[
                    "bwd_max"
                ]
            ) < max(
                bwd_payloads
            ):
                return False

            if int(
                candidate[
                    "bwd_min"
                ]
            ) > min(
                bwd_payloads
            ):
                return False


    return True


# ==============================================================================
# 6. MAXIMUM BIPARTITE MATCHING
# ==============================================================================

def can_match_all(
    corpus_rows,
    published_rows,
    compatibility,
):

    corpus_rows = list(
        corpus_rows
    )

    published_rows = set(
        published_rows
    )


    matched_pub_to_corpus = {}


    def dfs(
        corpus_row,
        seen,
    ):

        for published_row in compatibility[
            corpus_row
        ]:

            if published_row not in published_rows:
                continue

            if published_row in seen:
                continue

            seen.add(
                published_row
            )


            previous = matched_pub_to_corpus.get(
                published_row
            )


            if (
                previous is None
                or
                dfs(
                    previous,
                    seen,
                )
            ):

                matched_pub_to_corpus[
                    published_row
                ] = corpus_row

                return True


        return False


    for corpus_row in sorted(
        corpus_rows,
        key=lambda x: len(
            compatibility[
                x
            ]
        ),
    ):

        if not dfs(
            corpus_row,
            set(),
        ):

            return False


    return True


