def run_cmd(args, *, cwd=None, check=True):

    p = subprocess.run(
        [str(x) for x in args],
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
    )

    if check and p.returncode != 0:
        raise RuntimeError(
            "\nCommand failed:\n"
            + " ".join(str(x) for x in args)
            + "\n\n"
            + (p.stdout or "")
        )

    return (p.stdout or "").strip()


def git_cmd(*args, auth_header=None, check=True):

    command = ["git"]

    if auth_header is not None:

        command += [
            "-c",
            "credential.helper=",
            "-c",
            f"http.extraHeader=AUTHORIZATION: Basic {auth_header}",
        ]

    command += [
        str(x)
        for x in args
    ]

    return run_cmd(
        command,
        cwd=REPO,
        check=check,
    )


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as fh:

        while True:

            chunk = fh.read(
                8 * 1024 * 1024
            )

            if not chunk:
                break

            h.update(chunk)

    return h.hexdigest()


