# ==============================================================================
# 4. SHA HELPER
# ==============================================================================

def sha256_file(
    path,
    *,
    chunk_size=32 * 1024 * 1024,
):

    h = hashlib.sha256()

    total = 0


    with Path(path).open(
        "rb"
    ) as fh:

        while True:

            chunk = fh.read(
                chunk_size
            )

            if not chunk:
                break


            h.update(
                chunk
            )

            total += len(
                chunk
            )


    return (
        h.hexdigest(),
        total,
    )


# ==============================================================================
# 5. DOWNLOAD + BYTE VERIFY + METADATA ONLY
# ==============================================================================

print("=" * 112)
print("ACQUIRE + VERIFY")
print("=" * 112)


