print("=" * 112)


THU_MORNING = (
    ROOT
    / "Thursday-WorkingHours-Morning-WebAttacks.pcap_ISCX.csv.parquet"
)


schema = pq.ParquetFile(
    THU_MORNING
).schema_arrow


columns = list(
    schema.names
)


def q(name):

    return (
        '"'
        +
        str(
            name
        ).replace(
            '"',
            '""',
        )
        +
        '"'
    )


all_null_predicate = (
    " AND ".join(
        f"{q(name)} IS NULL"
        for name in columns
    )
)


any_nonnull_predicate = (
    " OR ".join(
        f"{q(name)} IS NOT NULL"
        for name in columns
    )
)


thu_path_sql = str(
    THU_MORNING
).replace(
    "'",
    "''",
)


(
    physical,
    label_null,
    all_columns_null,
    effective,
) = conn.execute(
    f"""
    SELECT
        COUNT(*)                                               AS physical,

        COUNT(*) FILTER (
            WHERE "Label" IS NULL
        )                                                      AS label_null,

        COUNT(*) FILTER (
            WHERE {all_null_predicate}
        )                                                      AS all_columns_null,

        COUNT(*) FILTER (
            WHERE "Label" IS NOT NULL
        )                                                      AS effective

    FROM read_parquet('{thu_path_sql}')
    """
).fetchone()


physical = int(
    physical
)

label_null = int(
    label_null
)

all_columns_null = int(
    all_columns_null
)

effective = int(
    effective
)


