# Numeric-compatible Arrow families.
def numeric_compatible(
    dtype,
):

    return (
        pa.types.is_integer(
            dtype
        )
        or
        pa.types.is_floating(
            dtype
        )
        or
        pa.types.is_decimal(
            dtype
        )
    )


