# ==============================================================================
# 9. LABEL CANONICALIZATION — FROZEN RULE
# ==============================================================================

DASH_TRANSLATION = str.maketrans(
    {
        "\u2010": "-",
        "\u2011": "-",
        "\u2012": "-",
        "\u2013": "-",
        "\u2014": "-",
        "\u2015": "-",
        "\u2212": "-",
    }
)


def canonicalize_labels(
    series,
):

    if series.isna().any():

        raise RuntimeError(
            "NULL label survived effective-row filter."
        )


    s = (
        series
        .astype(
            "string"
        )
        .str.strip()
        .str.translate(
            DASH_TRANSLATION
        )
        .str.replace(
            r"\s+",
            " ",
            regex=True,
        )
        .str.casefold()
    )


    if s.isna().any():

        raise RuntimeError(
            "Label canonicalization produced NULL."
        )


    if (
        s.str.len()
        ==
        0
    ).any():

        raise RuntimeError(
            "Empty target label encountered."
        )


    return s


