def threshold_metrics(
    y_true,
    probability,
    threshold,
):

    threshold = np.float32(
        threshold
    )


    pred = (
        probability
        >=
        threshold
    )


    y1 = (
        y_true
        ==
        1
    )

    y0 = ~y1


    tp = int(
        np.sum(
            pred
            &
            y1
        )
    )

    fp = int(
        np.sum(
            pred
            &
            y0
        )
    )

    fn = int(
        np.sum(
            (~pred)
            &
            y1
        )
    )

    tn = int(
        np.sum(
            (~pred)
            &
            y0
        )
    )


    accuracy = (
        tp + tn
    ) / (
        tp + tn + fp + fn
    )


    precision = (
        tp / (tp + fp)
        if (
            tp + fp
        ) > 0
        else 0.0
    )


    recall = (
        tp / (tp + fn)
        if (
            tp + fn
        ) > 0
        else 0.0
    )


    fpr = (
        fp / (fp + tn)
        if (
            fp + tn
        ) > 0
        else 0.0
    )


    fnr = (
        fn / (fn + tp)
        if (
            fn + tp
        ) > 0
        else 0.0
    )


    f1_den = (
        2 * tp
        +
        fp
        +
        fn
    )


    f1 = (
        2 * tp / f1_den
        if f1_den > 0
        else 0.0
    )


    f2_den = (
        5 * tp
        +
        4 * fn
        +
        fp
    )


    f2 = (
        5 * tp / f2_den
        if f2_den > 0
        else 0.0
    )


    return {
        "threshold":
            float(
                threshold
            ),

        "tp":
            tp,

        "tn":
            tn,

        "fp":
            fp,

        "fn":
            fn,

        "accuracy":
            float(
                accuracy
            ),

        "precision":
            float(
                precision
            ),

        "recall":
            float(
                recall
            ),

        "f1":
            float(
                f1
            ),

        "f2":
            float(
                f2
            ),

        "fpr":
            float(
                fpr
            ),

        "fnr":
            float(
                fnr
            ),
    }


def calibration_metrics(
    y_true,
    probability,
):

    p64 = probability.astype(
        np.float64,
        copy=False,
    )

    y64 = y_true.astype(
        np.float64,
        copy=False,
    )


    brier = float(
        np.mean(
            (
                p64
                -
                y64
            ) ** 2
        )
    )


    clipped = np.clip(
        p64,
        1e-15,
        1.0 - 1e-15,
    )


    log_loss = float(
        -np.mean(
            y64
            *
            np.log(
                clipped
            )
            +
            (
                1.0 - y64
            )
            *
            np.log(
                1.0 - clipped
            )
        )
    )


    bins = np.floor(
        p64
        *
        10.0
    ).astype(
        np.int8
    )

    bins = np.clip(
        bins,
        0,
        9,
    )


    ece = 0.0

    ece_bins = []


    for b in range(
        10
    ):

        mask = (
            bins
            ==
            b
        )

        count = int(
            mask.sum()
        )


        if count == 0:

            ece_bins.append(
                {
                    "bin":
                        b,

                    "count":
                        0,

                    "mean_probability":
                        None,

                    "empirical_rate":
                        None,

                    "absolute_gap":
                        None,
                }
            )

            continue


        confidence = float(
            p64[
                mask
            ].mean()
        )

        empirical = float(
            y64[
                mask
            ].mean()
        )

        gap = abs(
            confidence
            -
            empirical
        )


        ece += (
            count
            /
            len(
                p64
            )
        ) * gap


        ece_bins.append(
            {
                "bin":
                    b,

                "count":
                    count,

                "mean_probability":
                    confidence,

                "empirical_rate":
                    empirical,

                "absolute_gap":
                    float(
                        gap
                    ),
            }
        )


    return {
        "brier":
            brier,

        "log_loss":
            log_loss,

        "ece_10":
            float(
                ece
            ),

        "ece_bins":
            ece_bins,
    }


