# ==============================================================================
# 10. EXACT WEIGHTED METRIC ENGINE
# ==============================================================================

def metric_batch(
    bootstrap_group_counts,
    config,
):

    # bootstrap_group_counts:
    #     shape (B, G)
    #     exact resampled multiplicity of every joint equivalence group.

    order = config[
        "order"
    ]

    starts = config[
        "starts"
    ]

    sorted_label = config[
        "sorted_label"
    ]


    # Reorder group multiplicities into descending score order.
    w = bootstrap_group_counts[
        :,
        order
    ]


    # Total resampled weight at each distinct score.
    total_by_score = np.add.reduceat(
        w,
        starts,
        axis=1,
    ).astype(
        np.float64,
        copy=False,
    )


    # Positive resampled weight at each distinct score.
    positive_by_score = np.add.reduceat(
        w
        *
        sorted_label[
            None,
            :
        ],
        starts,
        axis=1,
    ).astype(
        np.float64,
        copy=False,
    )


    negative_by_score = (
        total_by_score
        -
        positive_by_score
    )


    # --------------------------------------------------------------------------
    # Non-interpolated Average Precision.
    # --------------------------------------------------------------------------

    cumulative_positive = np.cumsum(
        positive_by_score,
        axis=1,
        dtype=np.float64,
    )


    cumulative_total = np.cumsum(
        total_by_score,
        axis=1,
        dtype=np.float64,
    )


    precision = np.divide(
        cumulative_positive,
        cumulative_total,
        out=np.zeros_like(
            cumulative_positive,
            dtype=np.float64,
        ),
        where=(
            cumulative_total
            >
            0
        ),
    )


    pr_auc = np.sum(
        precision
        *
        (
            positive_by_score
            /
            float(
                EXPECTED_ATTACK
            )
        ),
        axis=1,
    )


    # --------------------------------------------------------------------------
    # Distinct-score trapezoidal ROC AUC.
    #
    # At each score:
    #   previous TPR = positives before entering this tied score
    #   current  TPR = positives after entering this tied score
    #   delta FPR    = negatives at this score / total negatives
    # --------------------------------------------------------------------------

    previous_positive = (
        cumulative_positive
        -
        positive_by_score
    )


    roc_auc = np.sum(
        (
            (
                previous_positive
                +
                cumulative_positive
            )
            /
            (
                2.0
                *
                float(
                    EXPECTED_ATTACK
                )
            )
        )
        *
        (
            negative_by_score
            /
            float(
                EXPECTED_BENIGN
            )
        ),
        axis=1,
    )


    # --------------------------------------------------------------------------
    # Brier.
    # --------------------------------------------------------------------------

    brier = (
        bootstrap_group_counts
        @
        config[
            "loss"
        ]
    ) / float(
        EXPECTED_ROWS
    )


    return {
        "pr_auc":
            np.asarray(
                pr_auc,
                dtype=np.float64,
            ),

        "roc_auc":
            np.asarray(
                roc_auc,
                dtype=np.float64,
            ),

        "brier":
            np.asarray(
                brier,
                dtype=np.float64,
            ),
    }


