def validate_point(
    name,
    actual,
    expected,
    tolerance=5e-12,
):

    print(
        name
    )


    for metric in [
        "pr_auc",
        "roc_auc",
        "brier",
    ]:

        delta = abs(
            actual[
                metric
            ]
            -
            expected[
                metric
            ]
        )


        print(
            f"  {metric:8s}"
            f" grouped={actual[metric]:.15f}"
            f" durable={expected[metric]:.15f}"
            f" |Δ|={delta:.3e}"
        )


        if delta > tolerance:

            raise RuntimeError(
                "\nGrouped bootstrap metric engine does not reproduce "
                "the frozen point estimate.\n"
                f"Vector: {name}\n"
                f"Metric: {metric}\n"
                f"Difference: {delta}"
            )


validate_point(
    "bridge62",
    point62,
    expected62,
)


validate_point(
    "bridge70 PUBLISHED",
    point70_pub,
    expected70_pub,
)


validate_point(
    "bridge70 FLAG_CORRECTED",
    point70_corr,
    expected70_corr,
)


