# ==============================================================================
# 15. PERCENTILE CI HELPER
# ==============================================================================

def percentile_ci(
    values,
):

    lower, upper = np.percentile(
        values,
        [
            2.5,
            97.5,
        ],
        method="linear",
    )


    return (
        float(
            lower
        ),
        float(
            upper
        ),
    )


def comparison_summary(
    name,
    point_a,
    point_b,
    boot_prefix,
):

    output = {}


    for metric in [
        "pr_auc",
        "roc_auc",
        "brier",
    ]:

        point_difference = float(
            point_a[
                metric
            ]
            -
            point_b[
                metric
            ]
        )


        bootstrap_key = (
            boot_prefix
            +
            "_"
            +
            metric
        )


        values = differences[
            bootstrap_key
        ]


        lower, upper = percentile_ci(
            values
        )


        output[
            metric
        ] = {
            "point_difference":
                point_difference,

            "bootstrap_mean_difference":
                float(
                    np.mean(
                        values
                    )
                ),

            "ci_2_5":
                lower,

            "ci_97_5":
                upper,

            "ci_excludes_zero":
                bool(
                    (
                        lower > 0.0
                    )
                    or
                    (
                        upper < 0.0
                    )
                ),
        }


    return {
        "comparison":
            name,

        "orientation":
            "A_MINUS_B",

        "bootstrap":
            output,
    }


