# ==============================================================================
# 8. LABEL RULE
# ==============================================================================

DASH_TRANSLATION = str.maketrans(
    {
        "\u2010": "-",
        "\u2011": "-",
        "\u2012": "-",
        "\u2013": "-",
        "\u2014": "-",
        "\u2015": "-",
        "\u2212": "-",
    }
)


def canonicalize_labels(series):

    if series.isna().any():

        raise RuntimeError(
            "NULL label survived frozen effective-row rule."
        )


    s = (
        series
        .astype(
            "string"
        )
        .str.strip()
        .str.translate(
            DASH_TRANSLATION
        )
        .str.replace(
            r"\s+",
            " ",
            regex=True,
        )
        .str.casefold()
    )


    if s.isna().any():

        raise RuntimeError(
            "Label canonicalization generated NULL."
        )


    if (
        s.str.len()
        ==
        0
    ).any():

        raise RuntimeError(
            "Empty label encountered."
        )


    return s


# ==============================================================================
# 9. MATERIALIZER
# ==============================================================================

conn = duckdb.connect(
    database=":memory:"
)


projection_sql = ",\n".join(
    (
        f"CAST({qident(SOURCE_MAPPING[source_feature])} AS DOUBLE) "
        f"AS {qident(source_feature)}"
    )
    for source_feature in FEATURE_ORDER
)


def materialize_files(
    file_specs,
    X_out,
    y_out,
    expected_total,
    split_name,
):

    cursor = 0

    numeric_audit = []

    label_counter = Counter()


    for day, filename, expected_rows in file_specs:

        path = (
            TARGET_ROOT
            /
            filename
        )


        if not path.is_file():

            raise RuntimeError(
                f"Missing source Parquet:\n{path}"
            )


        query = f"""
            SELECT
                {projection_sql},
                CAST("Label" AS VARCHAR) AS "__label__"
            FROM read_parquet('{sql_path(path)}')
            WHERE "Label" IS NOT NULL
        """


        t0 = time.time()


        df = conn.execute(
            query
        ).df()


        observed_rows = len(
            df
        )


        if observed_rows != expected_rows:

            raise RuntimeError(
                "\nFrozen effective row mismatch.\n"
                f"Split:    {split_name}\n"
                f"File:     {filename}\n"
                f"Expected: {expected_rows:,}\n"
                f"Actual:   {observed_rows:,}"
            )


        X = df[
            FEATURE_ORDER
        ].to_numpy(
            dtype=np.float64,
            copy=True,
        )


        if X.shape != (
            expected_rows,
            62,
        ):

            raise RuntimeError(
                f"Unexpected matrix shape: {X.shape}"
            )


        positive_inf = int(
            np.isposinf(
                X
            ).sum()
        )

        negative_inf = int(
            np.isneginf(
                X
            ).sum()
        )


        inf_mask = np.isinf(
            X
        )


        if inf_mask.any():

            X[
                inf_mask
            ] = np.nan


        nan_count = int(
            np.isnan(
                X
            ).sum()
        )


        canonical = canonicalize_labels(
            df[
                "__label__"
            ]
        )


        local_counter = Counter(
            canonical.tolist()
        )

        label_counter.update(
            local_counter
        )


        y = (
            canonical
            !=
            "benign"
        ).to_numpy(
            dtype=np.uint8
        )


        start = cursor

        stop = (
            start
            +
            expected_rows
        )


        X_out[
            start:stop,
            :
        ] = X

        y_out[
            start:stop
        ] = y


        print(
            f"{split_name:10s} "
            f"{day:20s}"
            f" rows={expected_rows:9,d}"
            f" benign={int((y == 0).sum()):9,d}"
            f" attack={int((y == 1).sum()):8,d}"
            f" +inf={positive_inf:6,d}"
            f" nan={nan_count:6,d}"
            f" seconds={time.time() - t0:6.2f}"
        )


        numeric_audit.append(
            {
                "split":
                    split_name,

                "day":
                    day,

                "file":
                    filename,

                "rows":
                    expected_rows,

                "positive_inf_to_nan":
                    positive_inf,

                "negative_inf_to_nan":
                    negative_inf,

                "nan_cells_after_inf_conversion":
                    nan_count,
            }
        )


        cursor = stop


        del df
        del X
        del y
        del canonical
        del inf_mask

        gc.collect()


    if cursor != expected_total:

        raise RuntimeError(
            f"{split_name} final row count mismatch."
        )


    return (
        numeric_audit,
        label_counter,
    )


