# ==============================================================================
# 17. FROZEN THRESHOLD GRID
# ==============================================================================

def threshold_row(
    pct,
):

    threshold = np.float32(
        pct
        /
        100.0
    )


    pred = (
        p_val
        >=
        threshold
    )


    y1 = (
        y_val
        ==
        1
    )

    y0 = ~y1


    tp = int(
        np.sum(
            pred
            &
            y1
        )
    )

    fp = int(
        np.sum(
            pred
            &
            y0
        )
    )

    fn = int(
        EXPECTED_VAL_ATTACK
        -
        tp
    )

    tn = int(
        EXPECTED_VAL_BENIGN
        -
        fp
    )


    return {
        "threshold_integer_percent":
            int(
                pct
            ),

        "threshold_float32_runtime":
            float(
                threshold
            ),

        "tp":
            tp,

        "tn":
            tn,

        "fp":
            fp,

        "fn":
            fn,
    }


grid = [
    threshold_row(
        pct
    )
    for pct in range(
        5,
        96,
    )
]


# ==============================================================================
# 18. EXACT RATIONAL OBJECTIVE HELPERS
# ==============================================================================

def f1_num_den(row):

    numerator = (
        2
        *
        row[
            "tp"
        ]
    )

    denominator = (
        2
        *
        row[
            "tp"
        ]
        +
        row[
            "fp"
        ]
        +
        row[
            "fn"
        ]
    )


    return (
        numerator,
        denominator,
    )


def f2_num_den(row):

    numerator = (
        5
        *
        row[
            "tp"
        ]
    )

    denominator = (
        5
        *
        row[
            "tp"
        ]
        +
        4
        *
        row[
            "fn"
        ]
        +
        row[
            "fp"
        ]
    )


    return (
        numerator,
        denominator,
    )


def rational_compare(
    n1,
    d1,
    n2,
    d2,
):

    left = (
        n1
        *
        d2
    )

    right = (
        n2
        *
        d1
    )


    if left > right:
        return 1

    if left < right:
        return -1

    return 0


# ==============================================================================
# 19. BALANCED THRESHOLD — EXACT FROZEN TIE BREAK
# ==============================================================================

balanced = None


for row in grid:

    if balanced is None:

        balanced = row
        continue


    n_new, d_new = f1_num_den(
        row
    )

    n_old, d_old = f1_num_den(
        balanced
    )


    objective_cmp = rational_compare(
        n_new,
        d_new,
        n_old,
        d_old,
    )


    if objective_cmp > 0:

        balanced = row
        continue


    if objective_cmp < 0:

        continue


    # Tie 1: LOWER_FPR.
    # Same validation benign denominator => lower FP.
    if row[
        "fp"
    ] < balanced[
        "fp"
    ]:

        balanced = row
        continue


    if row[
        "fp"
    ] > balanced[
        "fp"
    ]:

        continue


    # Tie 2: HIGHER_RECALL.
    # Same validation attack denominator => higher TP.
    if row[
        "tp"
    ] > balanced[
        "tp"
    ]:

        balanced = row
        continue


    if row[
        "tp"
    ] < balanced[
        "tp"
    ]:

        continue


    # Tie 3: CLOSER_TO_0_50.
    new_distance = abs(
        row[
            "threshold_integer_percent"
        ]
        -
        50
    )

    old_distance = abs(
        balanced[
            "threshold_integer_percent"
        ]
        -
        50
    )


    if new_distance < old_distance:

        balanced = row
        continue


    if new_distance > old_distance:

        continue


    # Tie 4: LOWER_THRESHOLD.
    if (
        row[
            "threshold_integer_percent"
        ]
        <
        balanced[
            "threshold_integer_percent"
        ]
    ):

        balanced = row


# ==============================================================================
# 20. SECURITY THRESHOLD
# ==============================================================================

security_candidates = [
    row
    for row in grid
    if (
        20
        *
        row[
            "fp"
        ]
    )
    <=
    EXPECTED_VAL_BENIGN
]


security = None


for row in security_candidates:

    if security is None:

        security = row
        continue


    n_new, d_new = f2_num_den(
        row
    )

    n_old, d_old = f2_num_den(
        security
    )


    objective_cmp = rational_compare(
        n_new,
        d_new,
        n_old,
        d_old,
    )


    if objective_cmp > 0:

        security = row
        continue


    if objective_cmp < 0:

        continue


    # Tie 1: lower FPR -> lower FP.
    if row[
        "fp"
    ] < security[
        "fp"
    ]:

        security = row
        continue


    if row[
        "fp"
    ] > security[
        "fp"
    ]:

        continue


    # Tie 2: higher recall -> higher TP.
    if row[
        "tp"
    ] > security[
        "tp"
    ]:

        security = row
        continue


    if row[
        "tp"
    ] < security[
        "tp"
    ]:

        continue


    # Tie 3: lower threshold.
    if (
        row[
            "threshold_integer_percent"
        ]
        <
        security[
            "threshold_integer_percent"
        ]
    ):

        security = row


# ==============================================================================
# 21. THRESHOLDED METRICS
# ==============================================================================

def expand_metrics(row):

    tp = row[
        "tp"
    ]

    tn = row[
        "tn"
    ]

    fp = row[
        "fp"
    ]

    fn = row[
        "fn"
    ]


    precision = (
        tp
        /
        (
            tp
            +
            fp
        )
        if (
            tp + fp
        ) > 0
        else 0.0
    )


    recall = (
        tp
        /
        (
            tp
            +
            fn
        )
        if (
            tp + fn
        ) > 0
        else 0.0
    )


    fpr = (
        fp
        /
        (
            fp
            +
            tn
        )
        if (
            fp + tn
        ) > 0
        else 0.0
    )


    fnr = (
        fn
        /
        (
            fn
            +
            tp
        )
        if (
            fn + tp
        ) > 0
        else 0.0
    )


    f1_num, f1_den = f1_num_den(
        row
    )

    f2_num, f2_den = f2_num_den(
        row
    )


    return {
        **row,

        "accuracy":
            float(
                (
                    tp
                    +
                    tn
                )
                /
                EXPECTED_VAL_ROWS
            ),

        "precision":
            float(
                precision
            ),

        "recall":
            float(
                recall
            ),

        "f1":
            float(
                f1_num
                /
                f1_den
                if f1_den
                else 0.0
            ),

        "f2":
            float(
                f2_num
                /
                f2_den
                if f2_den
                else 0.0
            ),

        "fpr":
            float(
                fpr
            ),

        "fnr":
            float(
                fnr
            ),
    }


standard = expand_metrics(
    grid[
        50
        -
        5
    ]
)


balanced_metrics = expand_metrics(
    balanced
)


security_metrics = (
    expand_metrics(
        security
    )
    if security is not None
    else None
)


