def run_cmd(
    args,
    *,
    cwd=None,
    check=True,
):

    try:

        p = subprocess.run(
            [str(x) for x in args],
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
        )

    except FileNotFoundError as exc:

        if check:
            raise

        return ""


    if check and p.returncode != 0:

        raise RuntimeError(
            "\nCommand failed:\n"
            + " ".join(
                str(x)
                for x in args
            )
            + "\n\n"
            + (p.stdout or "")
        )


    return (p.stdout or "").strip()


def git_cmd(
    *args,
    auth_header=None,
    check=True,
):

    cmd = [
        "git"
    ]


    if auth_header is not None:

        cmd += [
            "-c",
            "credential.helper=",
            "-c",
            f"http.extraHeader=AUTHORIZATION: Basic {auth_header}",
        ]


    cmd += [
        str(x)
        for x in args
    ]


    return run_cmd(
        cmd,
        cwd=REPO,
        check=check,
    )


def sha256_file(
    path,
):

    h = hashlib.sha256()


    with Path(path).open(
        "rb"
    ) as fh:

        while True:

            block = fh.read(
                8 * 1024 * 1024
            )


            if not block:
                break


            h.update(
                block
            )


    return h.hexdigest()


