def run_cmd(
    args,
    *,
    cwd=None,
    check=True,
):

    p = subprocess.run(
        [str(x) for x in args],
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
    )

    if check and p.returncode != 0:

        raise RuntimeError(
            "\nCommand failed:\n"
            + " ".join(
                str(x)
                for x in args
            )
            + "\n\n"
            + (p.stdout or "")
        )

    return (p.stdout or "").strip()


def git_cmd(
    *args,
    auth_header=None,
    check=True,
):

    cmd = [
        "git"
    ]

    if auth_header is not None:

        cmd += [
            "-c",
            "credential.helper=",
            "-c",
            f"http.extraHeader=AUTHORIZATION: Basic {auth_header}",
        ]

    cmd += [
        str(x)
        for x in args
    ]

    return run_cmd(
        cmd,
        cwd=REPO,
        check=check,
    )


def sha256_file(
    path,
):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as fh:

        while True:

            block = fh.read(
                16 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def sha256_array(
    array,
):

    arr = np.ascontiguousarray(
        array
    )

    return hashlib.sha256(
        arr.view(
            np.uint8
        )
    ).hexdigest()


def verify_sidecar(
    artifact,
    sidecar,
):

    if not artifact.is_file():

        raise RuntimeError(
            f"Missing artifact:\n{artifact}"
        )

    if not sidecar.is_file():

        raise RuntimeError(
            f"Missing SHA sidecar:\n{sidecar}"
        )


    actual = sha256_file(
        artifact
    )


    expected = (
        sidecar
        .read_text(
            encoding="utf-8"
        )
        .strip()
        .split()[0]
        .lower()
    )


    if actual != expected:

        raise RuntimeError(
            "\nSHA mismatch.\n"
            f"Artifact: {artifact}\n"
            f"Expected: {expected}\n"
            f"Actual:   {actual}"
        )


    return actual


def qident(
    value,
):

    return (
        '"'
        +
        str(
            value
        ).replace(
            '"',
            '""',
        )
        +
        '"'
    )


def sql_path(
    path,
):

    return str(
        path
    ).replace(
        "'",
        "''",
    )


