# ==============================================================================
# 15. SOURCE-VALIDATION GLOBAL METRICS
# ==============================================================================

pr_auc = float(
    average_precision_score(
        y_val,
        p_val,
    )
)


roc_auc = float(
    roc_auc_score(
        y_val,
        p_val,
    )
)


pr_excess = float(
    pr_auc
    -
    val_prevalence
)


pr_normalized = float(
    (
        pr_auc
        -
        val_prevalence
    )
    /
    (
        1.0
        -
        val_prevalence
    )
)


p64 = p_val.astype(
    np.float64,
    copy=False,
)


y64 = y_val.astype(
    np.float64,
    copy=False,
)


brier = float(
    np.mean(
        (
            p64
            -
            y64
        ) ** 2
    )
)


clipped = np.clip(
    p64,
    1e-15,
    1.0 - 1e-15,
)


log_loss = float(
    -np.mean(
        y64
        *
        np.log(
            clipped
        )
        +
        (
            1.0
            -
            y64
        )
        *
        np.log(
            1.0
            -
            clipped
        )
    )
)


bins = np.floor(
    p64
    *
    10.0
).astype(
    np.int8
)


bins = np.clip(
    bins,
    0,
    9,
)


ece = 0.0


for b in range(
    10
):

    mask = (
        bins
        ==
        b
    )


    count = int(
        mask.sum()
    )


    if count == 0:

        continue


    confidence = float(
        p64[
            mask
        ].mean()
    )


    empirical = float(
        y64[
            mask
        ].mean()
    )


    ece += (
        count
        /
        EXPECTED_VAL_ROWS
    ) * abs(
        confidence
        -
        empirical
    )


ece = float(
    ece
)


