def threshold_counts(
    pct,
):

    threshold = np.float32(
        pct
        /
        100.0
    )


    pred = (
        p_val70
        >=
        threshold
    )


    y1 = (
        y_val
        ==
        1
    )


    y0 = ~y1


    tp = int(
        np.sum(
            pred
            &
            y1
        )
    )


    fp = int(
        np.sum(
            pred
            &
            y0
        )
    )


    fn = (
        EXPECTED_VAL_ATTACK
        -
        tp
    )


    tn = (
        EXPECTED_VAL_BENIGN
        -
        fp
    )


    return {
        "threshold_integer_percent":
            int(
                pct
            ),

        "threshold_float32_runtime":
            float(
                threshold
            ),

        "tp":
            tp,

        "tn":
            tn,

        "fp":
            fp,

        "fn":
            fn,
    }


grid = [
    threshold_counts(
        pct
    )
    for pct in range(
        5,
        96,
    )
]


# ==============================================================================
# 20. EXACT RATIONAL OBJECTIVES
# ==============================================================================

def f1_fraction(
    row,
):

    return (
        2
        *
        row[
            "tp"
        ],
        2
        *
        row[
            "tp"
        ]
        +
        row[
            "fp"
        ]
        +
        row[
            "fn"
        ],
    )


def f2_fraction(
    row,
):

    return (
        5
        *
        row[
            "tp"
        ],
        5
        *
        row[
            "tp"
        ]
        +
        4
        *
        row[
            "fn"
        ]
        +
        row[
            "fp"
        ],
    )


def rational_cmp(
    n1,
    d1,
    n2,
    d2,
):

    left = (
        n1
        *
        d2
    )


    right = (
        n2
        *
        d1
    )


    if left > right:
        return 1


    if left < right:
        return -1


    return 0


# ==============================================================================
# 21. BALANCED THRESHOLD
# ==============================================================================

balanced = None


for row in grid:

    if balanced is None:

        balanced = row
        continue


    n1, d1 = f1_fraction(
        row
    )


    n2, d2 = f1_fraction(
        balanced
    )


    cmp = rational_cmp(
        n1,
        d1,
        n2,
        d2,
    )


    if cmp > 0:

        balanced = row
        continue


    if cmp < 0:

        continue


    # Lower FPR.
    if row[
        "fp"
    ] < balanced[
        "fp"
    ]:

        balanced = row
        continue


    if row[
        "fp"
    ] > balanced[
        "fp"
    ]:

        continue


    # Higher recall.
    if row[
        "tp"
    ] > balanced[
        "tp"
    ]:

        balanced = row
        continue


    if row[
        "tp"
    ] < balanced[
        "tp"
    ]:

        continue


    # Closer to 0.50.
    new_distance = abs(
        row[
            "threshold_integer_percent"
        ]
        -
        50
    )


    old_distance = abs(
        balanced[
            "threshold_integer_percent"
        ]
        -
        50
    )


    if new_distance < old_distance:

        balanced = row
        continue


    if new_distance > old_distance:

        continue


    # Lower threshold.
    if (
        row[
            "threshold_integer_percent"
        ]
        <
        balanced[
            "threshold_integer_percent"
        ]
    ):

        balanced = row


# ==============================================================================
# 22. SECURITY THRESHOLD
# ==============================================================================

security_candidates = [
    row
    for row in grid
    if (
        20
        *
        row[
            "fp"
        ]
    )
    <=
    EXPECTED_VAL_BENIGN
]


security = None


for row in security_candidates:

    if security is None:

        security = row
        continue


    n1, d1 = f2_fraction(
        row
    )


    n2, d2 = f2_fraction(
        security
    )


    cmp = rational_cmp(
        n1,
        d1,
        n2,
        d2,
    )


    if cmp > 0:

        security = row
        continue


    if cmp < 0:

        continue


    if row[
        "fp"
    ] < security[
        "fp"
    ]:

        security = row
        continue


    if row[
        "fp"
    ] > security[
        "fp"
    ]:

        continue


    if row[
        "tp"
    ] > security[
        "tp"
    ]:

        security = row
        continue


    if row[
        "tp"
    ] < security[
        "tp"
    ]:

        continue


    if (
        row[
            "threshold_integer_percent"
        ]
        <
        security[
            "threshold_integer_percent"
        ]
    ):

        security = row


# ==============================================================================
# 23. EXPAND THRESHOLD METRICS
# ==============================================================================

def expand(
    row,
):

    tp = row[
        "tp"
    ]

    tn = row[
        "tn"
    ]

    fp = row[
        "fp"
    ]

    fn = row[
        "fn"
    ]


    precision = (
        tp
        /
        (
            tp + fp
        )
        if (
            tp + fp
        )
        else 0.0
    )


    recall = (
        tp
        /
        (
            tp + fn
        )
        if (
            tp + fn
        )
        else 0.0
    )


    fpr = (
        fp
        /
        (
            fp + tn
        )
        if (
            fp + tn
        )
        else 0.0
    )


    fnr = (
        fn
        /
        (
            fn + tp
        )
        if (
            fn + tp
        )
        else 0.0
    )


    f1n, f1d = f1_fraction(
        row
    )


    f2n, f2d = f2_fraction(
        row
    )


    return {
        **row,

        "accuracy":
            float(
                (
                    tp + tn
                )
                /
                EXPECTED_VAL_ROWS
            ),

        "precision":
            float(
                precision
            ),

        "recall":
            float(
                recall
            ),

        "f1":
            float(
                f1n
                /
                f1d
                if f1d
                else 0.0
            ),

        "f2":
            float(
                f2n
                /
                f2d
                if f2d
                else 0.0
            ),

        "fpr":
            float(
                fpr
            ),

        "fnr":
            float(
                fnr
            ),
    }


standard = expand(
    grid[
        45
    ]
)


balanced_metrics = expand(
    balanced
)


security_metrics = (
    expand(
        security
    )
    if security is not None
    else None
)


