# ==============================================================================
# 18. FROZEN SOURCE-VALIDATION OPERATING POINTS ON TARGET
# ==============================================================================

def threshold_metrics(
    threshold,
):

    threshold = np.float32(
        threshold
    )


    pred = (
        p_target
        >=
        threshold
    )


    y1 = (
        y_target
        ==
        1
    )

    y0 = ~y1


    tp = int(
        np.sum(
            pred
            &
            y1
        )
    )

    fp = int(
        np.sum(
            pred
            &
            y0
        )
    )

    fn = int(
        EXPECTED_TARGET_ATTACK
        -
        tp
    )

    tn = int(
        EXPECTED_TARGET_BENIGN
        -
        fp
    )


    precision = (
        tp
        /
        (
            tp + fp
        )
        if (
            tp + fp
        )
        else 0.0
    )


    recall = (
        tp
        /
        (
            tp + fn
        )
        if (
            tp + fn
        )
        else 0.0
    )


    fpr = (
        fp
        /
        (
            fp + tn
        )
        if (
            fp + tn
        )
        else 0.0
    )


    fnr = (
        fn
        /
        (
            fn + tp
        )
        if (
            fn + tp
        )
        else 0.0
    )


    f1_den = (
        2 * tp
        +
        fp
        +
        fn
    )


    f2_den = (
        5 * tp
        +
        4 * fn
        +
        fp
    )


    return {
        "threshold":
            float(
                threshold
            ),

        "tp":
            tp,

        "tn":
            tn,

        "fp":
            fp,

        "fn":
            fn,

        "accuracy":
            float(
                (
                    tp + tn
                )
                /
                EXPECTED_TARGET_ROWS
            ),

        "precision":
            float(
                precision
            ),

        "recall":
            float(
                recall
            ),

        "f1":
            float(
                2 * tp / f1_den
                if f1_den
                else 0.0
            ),

        "f2":
            float(
                5 * tp / f2_den
                if f2_den
                else 0.0
            ),

        "fpr":
            float(
                fpr
            ),

        "fnr":
            float(
                fnr
            ),
    }


standard = threshold_metrics(
    STANDARD_THRESHOLD
)

balanced = threshold_metrics(
    BALANCED_THRESHOLD
)

security = threshold_metrics(
    SECURITY_THRESHOLD
)


