def run_cmd(
    args,
    *,
    cwd=None,
    check=True,
):

    p = subprocess.run(
        [str(x) for x in args],
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
    )

    if check and p.returncode != 0:

        raise RuntimeError(
            "\nCommand failed:\n"
            + " ".join(
                str(x)
                for x in args
            )
            + "\n\n"
            + (p.stdout or "")
        )

    return (p.stdout or "").strip()


def git_cmd(
    *args,
    auth_header=None,
    check=True,
):

    cmd = [
        "git"
    ]

    if auth_header is not None:

        cmd += [
            "-c",
            "credential.helper=",
            "-c",
            f"http.extraHeader=AUTHORIZATION: Basic {auth_header}",
        ]

    cmd += [
        str(x)
        for x in args
    ]

    return run_cmd(
        cmd,
        cwd=REPO,
        check=check,
    )


def sha256_file(
    path,
):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as fh:

        while True:

            block = fh.read(
                16 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def sha256_array(
    array,
):

    arr = np.ascontiguousarray(
        array
    )

    return hashlib.sha256(
        arr.view(
            np.uint8
        )
    ).hexdigest()


def verify_sidecar(
    artifact,
    sidecar,
):

    if not artifact.is_file():

        raise RuntimeError(
            f"Missing artifact:\n{artifact}"
        )

    if not sidecar.is_file():

        raise RuntimeError(
            f"Missing SHA sidecar:\n{sidecar}"
        )

    actual = sha256_file(
        artifact
    )

    expected = (
        sidecar
        .read_text(
            encoding="utf-8"
        )
        .strip()
        .split()[0]
        .lower()
    )

    if actual != expected:

        raise RuntimeError(
            "\nSHA mismatch.\n"
            f"Artifact: {artifact}\n"
            f"Expected: {expected}\n"
            f"Actual:   {actual}"
        )

    return actual


DASH_TRANSLATION = str.maketrans(
    {
        "\u2010": "-",
        "\u2011": "-",
        "\u2012": "-",
        "\u2013": "-",
        "\u2014": "-",
        "\u2015": "-",
        "\u2212": "-",
    }
)


def canonicalize_labels(
    series,
):

    if series.isna().any():

        raise RuntimeError(
            "NULL target label encountered."
        )

    s = (
        series
        .astype(
            "string"
        )
        .str.strip()
        .str.translate(
            DASH_TRANSLATION
        )
        .str.replace(
            r"\s+",
            " ",
            regex=True,
        )
        .str.casefold()
    )

    if s.isna().any():

        raise RuntimeError(
            "Label canonicalization produced NULL."
        )

    if (
        s.str.len()
        ==
        0
    ).any():

        raise RuntimeError(
            "Empty target label encountered."
        )

    return s


