# ==============================================================================
# 9. METRIC CONFIGURATION
# ==============================================================================

def make_metric_config(
    name,
    score,
):

    if score.dtype != np.float32:

        raise RuntimeError(
            f"{name}: probability storage is not float32."
        )


    if not np.isfinite(
        score
    ).all():

        raise RuntimeError(
            f"{name}: non-finite probability."
        )


    order = np.argsort(
        score,
        kind="stable",
    )[
        ::-1
    ]


    sorted_score = score[
        order
    ]


    starts = np.concatenate(
        [
            np.array(
                [
                    0
                ],
                dtype=np.int64,
            ),

            (
                np.flatnonzero(
                    sorted_score[
                        1:
                    ]
                    !=
                    sorted_score[
                        :-1
                    ]
                )
                +
                1
            ).astype(
                np.int64
            ),
        ]
    )


    sorted_label = group_label[
        order
    ].astype(
        np.uint8,
        copy=False,
    )


    score64 = score.astype(
        np.float64,
        copy=False,
    )


    loss = (
        score64
        -
        group_label.astype(
            np.float64,
            copy=False,
        )
    ) ** 2


    print(
        f"{name:12s}"
        f" groups={len(score):9,d}"
        f" distinct_scores={len(starts):9,d}"
    )


    return {
        "name":
            name,

        "order":
            order,

        "starts":
            starts,

        "sorted_label":
            sorted_label,

        "loss":
            loss,
    }


config62 = make_metric_config(
    "bridge62",
    group_p62,
)


config70 = make_metric_config(
    "bridge70",
    group_p70,
)


print()


# ==============================================================================
# 10. EXACT WEIGHTED METRIC ENGINE
# ==============================================================================

def metric_batch(
    bootstrap_group_counts,
    config,
):

    order = config[
        "order"
    ]


    starts = config[
        "starts"
    ]


    sorted_label = config[
        "sorted_label"
    ]


    w = bootstrap_group_counts[
        :,
        order
    ]


    total_by_score = np.add.reduceat(
        w,
        starts,
        axis=1,
    ).astype(
        np.float64,
        copy=False,
    )


    positive_by_score = np.add.reduceat(
        w
        *
        sorted_label[
            None,
            :
        ],
        starts,
        axis=1,
    ).astype(
        np.float64,
        copy=False,
    )


    negative_by_score = (
        total_by_score
        -
        positive_by_score
    )


    cumulative_positive = np.cumsum(
        positive_by_score,
        axis=1,
        dtype=np.float64,
    )


    cumulative_total = np.cumsum(
        total_by_score,
        axis=1,
        dtype=np.float64,
    )


    precision = np.divide(
        cumulative_positive,
        cumulative_total,
        out=np.zeros_like(
            cumulative_positive,
            dtype=np.float64,
        ),
        where=(
            cumulative_total
            >
            0
        ),
    )


    # Non-interpolated AP.
    pr_auc = np.sum(
        precision
        *
        (
            positive_by_score
            /
            float(
                EXPECTED_ATTACK
            )
        ),
        axis=1,
    )


    previous_positive = (
        cumulative_positive
        -
        positive_by_score
    )


    # Distinct-score trapezoidal ROC-AUC.
    roc_auc = np.sum(
        (
            (
                previous_positive
                +
                cumulative_positive
            )
            /
            (
                2.0
                *
                float(
                    EXPECTED_ATTACK
                )
            )
        )
        *
        (
            negative_by_score
            /
            float(
                EXPECTED_BENIGN
            )
        ),
        axis=1,
    )


    brier = (
        bootstrap_group_counts
        @
        config[
            "loss"
        ]
    ) / float(
        EXPECTED_ROWS
    )


    return {
        "pr_auc":
            np.asarray(
                pr_auc,
                dtype=np.float64,
            ),

        "roc_auc":
            np.asarray(
                roc_auc,
                dtype=np.float64,
            ),

        "brier":
            np.asarray(
                brier,
                dtype=np.float64,
            ),
    }


