def verify_point(
    name,
    actual,
    expected,
    tolerance=5e-12,
):

    print(
        name
    )


    for metric in [
        "pr_auc",
        "roc_auc",
        "brier",
    ]:

        delta = abs(
            actual[
                metric
            ]
            -
            expected[
                metric
            ]
        )


        print(
            f"  {metric:8s}"
            f" grouped={actual[metric]:.15f}"
            f" durable={expected[metric]:.15f}"
            f" |Δ|={delta:.3e}"
        )


        if delta > tolerance:

            raise RuntimeError(
                "\nGrouped metric engine failed durable point-estimate validation.\n"
                f"Vector: {name}\n"
                f"Metric: {metric}\n"
                f"|Δ|: {delta}"
            )


