def percentile_ci(
    values,
):

    low, high = np.percentile(
        values,
        [
            2.5,
            97.5,
        ],
        method="linear",
    )

    return (
        float(
            low
        ),
        float(
            high
        ),
    )


secondary_bootstrap = {}


for metric, values in [
    (
        "pr_auc",
        delta_pr,
    ),
    (
        "roc_auc",
        delta_roc,
    ),
    (
        "brier",
        delta_brier,
    ),
]:

    low, high = percentile_ci(
        values
    )


    secondary_bootstrap[
        metric
    ] = {
        "point_difference":
            point_delta[
                metric
            ],

        "bootstrap_mean_difference":
            float(
                values.mean()
            ),

        "ci_2_5":
            low,

        "ci_97_5":
            high,

        "ci_excludes_zero":
            bool(
                (
                    low > 0.0
                )
                or
                (
                    high < 0.0
                )
            ),
    }


