def run_cmd(
    args,
    *,
    cwd=None,
    check=True,
):

    p = subprocess.run(
        [str(x) for x in args],
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
    )

    if check and p.returncode != 0:

        raise RuntimeError(
            "\nCommand failed:\n"
            + " ".join(
                str(x)
                for x in args
            )
            + "\n\n"
            + (p.stdout or "")
        )

    return (p.stdout or "").strip()


def git_cmd(
    *args,
    auth_header=None,
    check=True,
):

    cmd = [
        "git"
    ]

    if auth_header is not None:

        cmd += [
            "-c",
            "credential.helper=",
            "-c",
            f"http.extraHeader=AUTHORIZATION: Basic {auth_header}",
        ]

    cmd += [
        str(x)
        for x in args
    ]

    return run_cmd(
        cmd,
        cwd=REPO,
        check=check,
    )


def sha256_file(
    path,
):

    path = Path(
        path
    )

    h = hashlib.sha256()

    with path.open(
        "rb"
    ) as fh:

        while True:

            block = fh.read(
                16 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def verify_sidecar(
    artifact,
    sidecar,
):

    artifact = Path(
        artifact
    )

    sidecar = Path(
        sidecar
    )

    if not artifact.is_file():

        raise RuntimeError(
            f"Missing artifact:\n{artifact}"
        )

    if not sidecar.is_file():

        raise RuntimeError(
            f"Missing sidecar:\n{sidecar}"
        )

    actual = sha256_file(
        artifact
    )

    expected = (
        sidecar
        .read_text(
            encoding="utf-8"
        )
        .strip()
        .split()[0]
    )

    if actual != expected:

        raise RuntimeError(
            "\nSHA mismatch:\n"
            f"Artifact: {artifact}\n"
            f"Expected: {expected}\n"
            f"Actual:   {actual}"
        )

    return actual


def write_text(
    path,
    content,
):

    path = Path(
        path
    )

    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    path.write_text(
        content.rstrip()
        +
        "\n",
        encoding="utf-8",
    )


def md_float(
    x,
    digits=6,
):

    if x is None:
        return "NA"

    return f"{float(x):.{digits}f}"


def latex_escape(
    value,
):

    value = str(
        value
    )

    replacements = {
        "&": r"\&",
        "%": r"\%",
        "$": r"\$",
        "#": r"\#",
        "_": r"\_",
        "{": r"\{",
        "}": r"\}",
    }

    for old, new in replacements.items():

        value = value.replace(
            old,
            new,
        )

    return value


def comparison_lookup(
    comparisons,
    name,
):

    matches = [
        x
        for x in comparisons
        if x.get(
            "comparison"
        ) == name
    ]

    if len(
        matches
    ) != 1:

        raise RuntimeError(
            f"Expected one comparison named {name}, got {len(matches)}"
        )

    return matches[
        0
    ]


def append_marked_section(
    path,
    begin_marker,
    end_marker,
    body,
):

    path = Path(
        path
    )

    original = (
        path.read_text(
            encoding="utf-8"
        )
        if path.is_file()
        else ""
    )

    block = (
        f"{begin_marker}\n\n"
        f"{body.strip()}\n\n"
        f"{end_marker}"
    )

    if begin_marker in original:

        start = original.index(
            begin_marker
        )

        if end_marker not in original[
            start:
        ]:

            raise RuntimeError(
                f"Found begin marker but no end marker in {path}"
            )

        end = (
            original.index(
                end_marker,
                start,
            )
            +
            len(
                end_marker
            )
        )

        updated = (
            original[
                :start
            ].rstrip()
            +
            "\n\n"
            +
            block
            +
            "\n"
            +
            original[
                end:
            ].lstrip(
                "\n"
            )
        )

    else:

        updated = (
            original.rstrip()
            +
            "\n\n"
            +
            block
            +
            "\n"
        )

    path.write_text(
        updated,
        encoding="utf-8",
    )


