table2_rows = []


def add_bootstrap_comparison(
    direction,
    comparison_name,
    source,
):

    for metric in [
        "pr_auc",
        "roc_auc",
        "brier",
    ]:

        metric_result = source[
            metric
        ]

        table2_rows.append(
            {
                "direction":
                    direction,

                "comparison":
                    comparison_name,

                "metric":
                    metric.upper(),

                "point_difference":
                    float(
                        metric_result[
                            "point_difference"
                        ]
                    ),

                "ci_2_5":
                    float(
                        metric_result[
                            "ci_2_5"
                        ]
                    ),

                "ci_97_5":
                    float(
                        metric_result[
                            "ci_97_5"
                        ]
                    ),

                "ci_excludes_zero":
                    bool(
                        metric_result[
                            "ci_excludes_zero"
                        ]
                    ),

                "replicates":
                    2000,

                "seed":
                    42,
            }
        )


add_bootstrap_comparison(
    "IDS2018 -> CICIDS2017",
    "bridge70 PUBLISHED - bridge62 PUBLISHED",
    pub_cmp[
        "bootstrap"
    ],
)


add_bootstrap_comparison(
    "IDS2018 -> CICIDS2017",
    "bridge70 FLAG_CORRECTED - bridge62 FLAG_CORRECTED",
    corr_cmp[
        "bootstrap"
    ],
)


add_bootstrap_comparison(
    "IDS2018 -> CICIDS2017",
    "bridge70 FLAG_CORRECTED - bridge70 PUBLISHED",
    artifact_cmp[
        "bootstrap"
    ],
)


add_bootstrap_comparison(
    "CICIDS2017 -> IDS2018",
    "bridge70 - bridge62",
    secondary_comparison,
)


