# 31. GIT AUTHOR SAFETY
# ==============================================================================

author_name = git_cmd(
    "config",
    "--local",
    "--get",
    "user.name",
    check=False,
)


author_email = git_cmd(
    "config",
    "--local",
    "--get",
    "user.email",
    check=False,
)


if not author_name:

    git_cmd(
        "config",
        "--local",
        "user.name",
        git_cmd(
            "log",
            "-1",
            "--format=%an",
        ),
    )


if not author_email:

    git_cmd(
        "config",
        "--local",
        "user.email",
        git_cmd(
            "log",
            "-1",
            "--format=%ae",
        ),
    )


